/* Deutsch Trainer — A0/A1 foundation grammar + drills.
   Explanations in the chosen support language (en/fa); German stays German.
   lv: 1=A0 2=A1 · sk = skill for the "Practise this" button.
   GRAM_A1 = lessons · DRILL_A1 = gap drills keyed by lesson id (gid).  */
window.GRAM_A1=[

/* ============ A0 ============ */
{id:'nomen-gross',ic:'🔠',lv:1,sk:'Beginner',
 title:{en:'Nouns: capitals & gender',fa:'اسم‌ها: حرف بزرگ و جنس'},
 sub:{en:'Two things every noun has',fa:'دو چیزی که هر اسم دارد'},
 blocks:[
  {type:'text',md:{en:'Open any German text and you will see capital letters in the middle of sentences. That is not a mistake and not emphasis: <b>every noun is capitalised</b>, always, everywhere in the sentence. „Ich kaufe <b>Brot</b> und <b>Milch</b>.“',
        fa:'در هر متن آلمانی حرف‌های بزرگ وسط جمله می‌بینی. این اشتباه یا تأکید نیست: <b>هر اسم با حرف بزرگ نوشته می‌شود</b>، همیشه و در هر جای جمله. «Ich kaufe <b>Brot</b> und <b>Milch</b>.»'}},
  {type:'rule',md:{en:'Capitalised: <b>nouns</b>, the first word of a sentence, and the formal <b>Sie</b>. Everything else stays small — verbs, adjectives, and even <b>ich</b> („I“ is lowercase in German!).',
        fa:'با حرف بزرگ: <b>اسم‌ها</b>، اولین کلمهٔ جمله، و <b>Sie</b>ی رسمی. بقیه کوچک می‌مانند — فعل‌ها، صفت‌ها و حتی <b>ich</b> («من» در آلمانی کوچک است!).'}},
  {type:'examples',items:[
   {de:'Der Hund schläft.',en:'The dog is sleeping.',say:'Der Hund schläft.'},
   {de:'Ich kaufe Brot und Milch.',en:'I buy bread and milk.',say:'Ich kaufe Brot und Milch.'},
   {de:'Das Kind liest ein Buch.',en:'The child is reading a book.',say:'Das Kind liest ein Buch.'},
   {de:'Mein Freund hat heute Zeit.',en:'My friend has time today.',say:'Mein Freund hat heute Zeit.'},
   {de:'Wir lernen Deutsch.',en:'We are learning German.',say:'Wir lernen Deutsch.'}]},
  {type:'warn',md:{en:'The two mistakes English speakers make: writing „ein hund“ (a noun must be big) and writing „Ich Lerne Deutsch“ (a verb must stay small). German capitals carry information — they tell your reader instantly which word is the thing being talked about. Treat a missing capital as a spelling error, because that is what it is.',
        fa:'دو اشتباه رایج: نوشتن «ein hund» (اسم باید بزرگ باشد) و نوشتن «Ich Lerne Deutsch» (فعل باید کوچک بماند). حرف بزرگ در آلمانی اطلاعات می‌دهد — فوراً نشان می‌دهد کدام کلمه «چیز» است. نبودنش غلط املایی است.'}},
  {type:'text',md:{en:'The second thing: every noun also has a <b>gender</b> — <b class="deword">der</b> (masculine), <b class="deword">die</b> (feminine) or <b class="deword">das</b> (neuter). This is pure grammar, not biology. A table is <i>der</i>, a door is <i>die</i>, and a girl (<i>das Mädchen</i>) is <i>das</i>. The gender decides how the article, the adjective and the pronoun around that noun will look, so it is never just decoration.',
        fa:'نکتهٔ دوم: هر اسم یک <b>جنس</b> هم دارد — <b class="deword">der</b> (مذکر)، <b class="deword">die</b> (مؤنث) یا <b class="deword">das</b> (خنثی). این فقط دستور زبان است، نه زیست‌شناسی. میز <i>der</i>، در <i>die</i> و دختر (<i>das Mädchen</i>) <i>das</i> است. جنس شکل حرف تعریف، صفت و ضمیر را تعیین می‌کند.'}},
  {type:'table',head:['Article','Noun','English','Gender'],rows:[
   ['*der','Tisch','table','masculine'],
   ['*die','Lampe','lamp','feminine'],
   ['*das','Fenster','window','neuter'],
   ['*die','Kinder','children','plural (always die)']],
   cap:{en:'the plural article is die for all three genders',fa:'حرف تعریف جمع برای هر سه جنس die است'}},
  {type:'tip',md:{en:'From today, never learn a noun alone. Learn <b>das Fenster</b>, not „Fenster“. Say the article out loud with the word every single time — it costs nothing now and saves you years later. Many learners even colour-code: blue = der, red = die, green = das.',
        fa:'از امروز هیچ اسمی را تنها یاد نگیر. <b>das Fenster</b> را یاد بگیر، نه «Fenster». حرف تعریف را هر بار با کلمه بلند بگو — الان هیچ هزینه‌ای ندارد و بعدها سال‌ها وقت صرفه‌جویی می‌کند.'}},
  {type:'quiz',q:{en:'Which sentence is written correctly?',fa:'کدام جمله درست نوشته شده است؟'},
   a:'Ich esse einen Apfel.',o:['ich esse einen Apfel.','Ich Esse einen apfel.','Ich esse Einen Apfel.'],
   ex:{en:'Sentence start → <b>I</b>ch. Noun → <b>A</b>pfel. Verb <i>esse</i> and article <i>einen</i> stay small.',
       fa:'آغاز جمله → <b>I</b>ch. اسم → <b>A</b>pfel. فعل <i>esse</i> و حرف تعریف <i>einen</i> کوچک می‌مانند.'}}
 ]},

/* ============ A1 ============ */
{id:'gender-regeln',ic:'🔍',lv:2,sk:'Articles',
 title:{en:'Guessing the gender',fa:'حدس زدن جنس اسم'},
 sub:{en:'Endings that give it away',fa:'پایانه‌هایی که لو می‌دهند'},
 blocks:[
  {type:'text',md:{en:'Nobody can guess the gender of <i>every</i> German noun — but you can guess most of them. The trick is the <b>ending</b> of the word. Hundreds of nouns share a handful of endings, and each ending belongs to one gender with almost no exceptions.',
        fa:'هیچ‌کس نمی‌تواند جنس <i>همهٔ</i> اسم‌های آلمانی را حدس بزند — اما بیشترشان را می‌توان. کلید، <b>پایانهٔ</b> کلمه است. صدها اسم چند پایانهٔ مشترک دارند و هر پایانه تقریباً بدون استثنا به یک جنس تعلق دارد.'}},
  {type:'table',head:['Ending','→','Example','English'],rows:[
   ['-ung','*die','die Zeitung','newspaper'],
   ['-heit','*die','die Freiheit','freedom'],
   ['-keit','*die','die Möglichkeit','possibility'],
   ['-schaft','*die','die Freundschaft','friendship'],
   ['-ion','*die','die Information','information'],
   ['-ei','*die','die Bäckerei','bakery']],
   cap:{en:'feminine endings — the most reliable group of all',fa:'پایانه‌های مؤنث — قابل‌اعتمادترین گروه'}},
  {type:'table',head:['Ending','→','Example','English'],rows:[
   ['-chen','*das','das Brötchen','bread roll'],
   ['-lein','*das','das Fräulein','young lady'],
   ['-ment','*das','das Dokument','document'],
   ['-um','*das','das Museum','museum']],
   cap:{en:'-chen and -lein are the diminutive endings („little …“)',fa:'‎-chen و -lein پایانه‌های تصغیر هستند («کوچکِ …»)'}},
  {type:'table',head:['Group','→','Examples'],rows:[
   ['-er (a person who does it)','*der','der Lehrer, der Arbeiter'],
   ['-ling','*der','der Lehrling, der Frühling'],
   ['-ismus','*der','der Kapitalismus, der Tourismus'],
   ['days of the week','*der','der Montag, der Sonntag'],
   ['months','*der','der Januar, der Mai'],
   ['seasons','*der','der Sommer, der Winter'],
   ['weather words','*der','der Regen, der Wind, der Schnee']],
   cap:{en:'time and weather are masculine — a very useful block',fa:'زمان و هوا مذکرند — بلوکی بسیار کاربردی'}},
  {type:'rule',md:{en:'When the ending and the meaning disagree, <b>the ending wins</b>. <i>das Mädchen</i> (girl) and <i>das Fräulein</i> are neuter because <b>-chen</b> and <b>-lein</b> are neuter — grammar beats biology every time.',
        fa:'وقتی پایانه و معنا با هم نمی‌خوانند، <b>پایانه برنده است</b>. <i>das Mädchen</i> (دختر) خنثی است چون <b>-chen</b> خنثی است — دستور زبان همیشه بر زیست‌شناسی غلبه می‌کند.'}},
  {type:'warn',md:{en:'<b>-er is the weak link.</b> It is only masculine when it means a person or a doer (<i>der Lehrer, der Computer</i>). Plenty of other -er nouns are not: <b>die</b> Mutter, <b>die</b> Butter, <b>die</b> Nummer, <b>das</b> Fenster, <b>das</b> Wasser, <b>das</b> Zimmer. So never finish a word in -er and feel safe.',
        fa:'<b>-er حلقهٔ ضعیف است.</b> فقط وقتی مذکر است که معنای شخص یا انجام‌دهنده بدهد (<i>der Lehrer</i>). اسم‌های دیگری با -er این‌طور نیستند: <b>die</b> Mutter، <b>die</b> Butter، <b>die</b> Nummer، <b>das</b> Fenster، <b>das</b> Wasser، <b>das</b> Zimmer.'}},
  {type:'examples',items:[
   {de:'Die Rechnung ist zu hoch.',en:'The bill is too high. (-ung → die)',say:'Die Rechnung ist zu hoch.'},
   {de:'Das Brötchen kostet einen Euro.',en:'The roll costs one euro. (-chen → das)',say:'Das Brötchen kostet einen Euro.'},
   {de:'Der Frühling kommt bald.',en:'Spring is coming soon. (-ling → der)',say:'Der Frühling kommt bald.'},
   {de:'Die Wohnung ist klein.',en:'The flat is small. (-ung → die)',say:'Die Wohnung ist klein.'},
   {de:'Das Zentrum ist weit weg.',en:'The centre is far away. (-um → das)',say:'Das Zentrum ist weit weg.'},
   {de:'Der Montag ist mein schlechtester Tag.',en:'Monday is my worst day. (day → der)',say:'Der Montag ist mein schlechtester Tag.'}]},
  {type:'tip',md:{en:'Learn this one sentence as a chant: <b>„Zeit und Wetter sind der, kleine Dinge sind das, und -ung ist immer die.“</b> („Time and weather are der, small things are das, and -ung is always die.“) It covers an astonishing share of everyday nouns.',
        fa:'این جمله را مثل یک ورد حفظ کن: <b>«Zeit und Wetter sind der, kleine Dinge sind das, und -ung ist immer die.»</b> («زمان و هوا der، چیزهای کوچک das، و -ung همیشه die.») بخش شگفت‌آوری از اسم‌های روزمره را پوشش می‌دهد.'}},
  {type:'quiz',q:{en:'You meet a new noun: <b>Rechnung</b>. Which article does it take?',fa:'به اسم تازهٔ <b>Rechnung</b> برمی‌خوری. کدام حرف تعریف را می‌گیرد؟'},
   a:'die',o:['der','das','den'],
   ex:{en:'<b>-ung</b> is feminine without exception → <b>die</b> Rechnung. Same for Zeitung, Wohnung, Prüfung, Meinung.',
       fa:'<b>-ung</b> بی‌استثنا مؤنث است → <b>die</b> Rechnung. همین‌طور Zeitung، Wohnung، Prüfung، Meinung.'}}
 ]},

{id:'einkein',ic:'1️⃣',lv:2,sk:'Articles',
 title:{en:'ein, eine, kein — and no article',fa:'ein، eine، kein — و بدون حرف تعریف'},
 sub:{en:'„a“, „not a“, and nothing at all',fa:'«یک»، «هیچ»، و هیچ‌چیز'},
 blocks:[
  {type:'text',md:{en:'<b class="deword">ein</b> is the German „a / an“. Its shape copies the gender of the noun: <b>ein</b> Mann (m), <b>eine</b> Frau (f), <b>ein</b> Kind (n). Notice that masculine and neuter look identical in the nominative — the difference only shows up in the accusative.',
        fa:'<b class="deword">ein</b> همان «یک» آلمانی است. شکلش از جنس اسم پیروی می‌کند: <b>ein</b> Mann (مذکر)، <b>eine</b> Frau (مؤنث)، <b>ein</b> Kind (خنثی). مذکر و خنثی در حالت فاعلی یکسان‌اند و تفاوت فقط در حالت مفعولی دیده می‌شود.'}},
  {type:'table',head:['','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ (subject)','ein','eine','ein','— / keine'],
   ['Akkusativ (object)','*einen','eine','ein','— / keine']],
   cap:{en:'only the masculine changes: ein → einen',fa:'فقط مذکر تغییر می‌کند: ein → einen'}},
  {type:'rule',md:{en:'To say „no / not a / not any“, put a <b>k</b> in front: <b class="deword">kein, keine, keinen</b>. It takes exactly the same endings as <i>ein</i> — and unlike <i>ein</i>, it also has a plural: <b>keine</b>.',
        fa:'برای گفتن «هیچ / نه یک»، یک <b>k</b> جلویش بگذار: <b class="deword">kein، keine، keinen</b>. دقیقاً همان پایانه‌های <i>ein</i> را می‌گیرد — و برخلاف <i>ein</i> جمع هم دارد: <b>keine</b>.'}},
  {type:'examples',items:[
   {de:'Ich habe einen Hund.',en:'I have a dog. (der Hund → einen)',say:'Ich habe einen Hund.'},
   {de:'Hast du eine Frage?',en:'Do you have a question?',say:'Hast du eine Frage?'},
   {de:'Das ist ein Problem.',en:'That is a problem.',say:'Das ist ein Problem.'},
   {de:'Ich habe kein Geld.',en:'I have no money.',say:'Ich habe kein Geld.'},
   {de:'Ich trinke keinen Alkohol.',en:'I don’t drink alcohol.',say:'Ich trinke keinen Alkohol.'},
   {de:'Wir haben keine Zeit.',en:'We have no time.',say:'Wir haben keine Zeit.'}]},
  {type:'text',md:{en:'Now the part textbooks rush past: German often uses <b>no article at all</b>, where English insists on one. Three big cases: <b>professions and nationalities</b> after <i>sein/werden</i> („Ich bin Lehrer“), <b>uncountable / mass nouns</b> („Ich trinke Wasser“, „Wir haben Zeit“), and the <b>indefinite plural</b> („Ich kaufe Äpfel“) — because <i>ein</i> simply has no plural.',
        fa:'و اکنون بخشی که کتاب‌ها سریع از آن می‌گذرند: آلمانی اغلب <b>هیچ حرف تعریفی</b> نمی‌گیرد، جایی که انگلیسی اصرار دارد. سه مورد مهم: <b>شغل و ملیت</b> بعد از <i>sein/werden</i> («Ich bin Lehrer»)، <b>اسم‌های غیرقابل‌شمارش</b> («Ich trinke Wasser») و <b>جمع نامعین</b> («Ich kaufe Äpfel») — چون <i>ein</i> جمع ندارد.'}},
  {type:'contrast',cols:[
   {t:'ein → kein',md:{en:'If the noun has <b>ein</b> or <b>no article</b>, negate it with <b>kein</b>.<br>„Ich habe ein Auto.“ → „Ich habe <b>kein</b> Auto.“<br>„Ich habe Zeit.“ → „Ich habe <b>keine</b> Zeit.“<br>„Er ist Lehrer.“ → „Er ist <b>kein</b> Lehrer.“',
       fa:'اگر اسم <b>ein</b> دارد یا <b>بدون حرف تعریف</b> است، با <b>kein</b> منفی کن.<br>«Ich habe ein Auto.» → «Ich habe <b>kein</b> Auto.»'}},
   {t:'der / mein → nicht',md:{en:'If the noun already has <b>der/die/das</b> or a possessive, negate with <b>nicht</b>.<br>„Das ist mein Auto.“ → „Das ist <b>nicht</b> mein Auto.“<br>„Ich kenne den Mann.“ → „Ich kenne den Mann <b>nicht</b>.“',
       fa:'اگر اسم از قبل <b>der/die/das</b> یا ضمیر ملکی دارد، با <b>nicht</b> منفی کن.<br>«Das ist <b>nicht</b> mein Auto.»'}}]},
  {type:'warn',md:{en:'Do not say „Ich bin <s>ein</s> Lehrer“ as your default. German states a profession bare: <b>„Ich bin Lehrer.“ / „Sie ist Ärztin.“ / „Er ist Student.“</b> The article only comes back when you describe <i>what kind</i> („Er ist ein guter Lehrer“). The same goes for nationality: <b>„Ich bin Deutscher.“</b>, not „ein Deutscher“ by default.',
        fa:'به‌طور پیش‌فرض نگو «Ich bin <s>ein</s> Lehrer». آلمانی شغل را بدون حرف تعریف می‌گوید: <b>«Ich bin Lehrer.» / «Sie ist Ärztin.»</b> حرف تعریف فقط وقتی برمی‌گردد که <i>چگونه بودن</i> را توصیف کنی («Er ist ein guter Lehrer»). ملیت هم همین‌طور.'}},
  {type:'quiz',q:{en:'„Ich habe ___ Auto.“ — you want to say you have no car.',fa:'«Ich habe ___ Auto.» — می‌خواهی بگویی ماشین نداری.'},
   a:'kein',o:['keine','keinen','nicht'],
   ex:{en:'<i>das Auto</i> is neuter, and neuter does not change in the accusative → <b>kein</b> Auto. „nicht“ would need a definite noun: „nicht mein Auto“.',
       fa:'<i>das Auto</i> خنثی است و خنثی در حالت مفعولی تغییر نمی‌کند → <b>kein</b> Auto. «nicht» به اسم معین نیاز دارد: «nicht mein Auto».'}}
 ]},

{id:'pronomen-akk',ic:'👉',lv:2,sk:'Cases',
 title:{en:'Object pronouns (Akkusativ)',fa:'ضمایر مفعولی (آکوزاتیو)'},
 sub:{en:'mich, dich, ihn, sie, es…',fa:'mich، dich، ihn، sie، es…'},
 blocks:[
  {type:'text',md:{en:'When a person or a thing <b>receives</b> the action, German swaps the pronoun for its accusative form. English does the same (I → me, he → him), so the idea is familiar — only the forms are new.',
        fa:'وقتی شخص یا چیزی <b>دریافت‌کنندهٔ</b> کنش است، آلمانی ضمیر را با شکل مفعولی‌اش عوض می‌کند. انگلیسی هم همین کار را می‌کند (I → me، he → him)، پس ایده آشناست و فقط شکل‌ها تازه‌اند.'}},
  {type:'table',head:['Subject','Object (Akk.)','English'],rows:[
   ['ich','*mich','me'],['du','*dich','you (one friend)'],
   ['er','*ihn','him / it (der)'],['sie','sie','her / it (die)'],
   ['es','es','it (das)'],['wir','*uns','us'],
   ['ihr','*euch','you (friends)'],['sie','sie','them'],['Sie','Sie','you (formal)']],
   cap:{en:'only four forms are really new: mich, dich, ihn, uns/euch',fa:'فقط چند شکل واقعاً تازه‌اند: mich، dich، ihn، uns، euch'}},
  {type:'examples',items:[
   {de:'Ich liebe dich.',en:'I love you.',say:'Ich liebe dich.'},
   {de:'Kennst du ihn?',en:'Do you know him?',say:'Kennst du ihn?'},
   {de:'Er ruft uns heute Abend an.',en:'He is calling us tonight.',say:'Er ruft uns heute Abend an.'},
   {de:'Ich verstehe Sie nicht.',en:'I don’t understand you. (formal)',say:'Ich verstehe Sie nicht.'},
   {de:'Wo seid ihr? Ich suche euch!',en:'Where are you? I’m looking for you!',say:'Wo seid ihr? Ich suche euch!'}]},
  {type:'rule',md:{en:'For a <b>thing</b>, the pronoun follows the <b>gender of the German noun</b>, not the English word „it“. <i>der</i> Tisch → <b>ihn</b> · <i>die</i> Lampe → <b>sie</b> · <i>das</i> Buch → <b>es</b>.',
        fa:'برای یک <b>چیز</b>، ضمیر از <b>جنس اسم آلمانی</b> پیروی می‌کند، نه از «it» انگلیسی. <i>der</i> Tisch → <b>ihn</b> · <i>die</i> Lampe → <b>sie</b> · <i>das</i> Buch → <b>es</b>.'}},
  {type:'warn',md:{en:'This is the single most common beginner error: translating „it“ as <b>es</b> every time. „Der Kaffee ist gut — ich trinke <s>es</s> gern“ is wrong; it must be <b>ihn</b>, because <i>Kaffee</i> is masculine. Your German pronoun is decided by the article you learned with the word — which is exactly why you learn the article with the word.',
        fa:'رایج‌ترین خطای مبتدیان: ترجمهٔ «it» به <b>es</b> در همهٔ موارد. «Der Kaffee ist gut — ich trinke <s>es</s> gern» غلط است؛ باید <b>ihn</b> باشد، چون <i>Kaffee</i> مذکر است. ضمیر تو را همان حرف تعریفی تعیین می‌کند که با کلمه یاد گرفتی.'}},
  {type:'examples',items:[
   {de:'Der Kaffee? Ich trinke ihn gern.',en:'The coffee? I like drinking it.',say:'Der Kaffee? Ich trinke ihn gern.'},
   {de:'Die Suppe? Ich esse sie später.',en:'The soup? I’ll eat it later.',say:'Die Suppe? Ich esse sie später.'},
   {de:'Das Brot? Ich kaufe es morgen.',en:'The bread? I’ll buy it tomorrow.',say:'Das Brot? Ich kaufe es morgen.'},
   {de:'Die Schlüssel? Ich habe sie.',en:'The keys? I have them.',say:'Die Schlüssel? Ich habe sie.'}]},
  {type:'tip',md:{en:'Memory hook: in the accusative, <b>masculine always ends in -n</b>: de<b>n</b>, eine<b>n</b>, meine<b>n</b>, ih<b>n</b>. If a masculine word is the object and you cannot hear an -n, something is missing.',
        fa:'قلاب حافظه: در حالت مفعولی، <b>مذکر همیشه به -n ختم می‌شود</b>: de<b>n</b>، eine<b>n</b>، meine<b>n</b>، ih<b>n</b>. اگر کلمهٔ مذکری مفعول است و -n نمی‌شنوی، چیزی جا افتاده.'}},
  {type:'quiz',q:{en:'„Ich kaufe den Tisch. — Ich kaufe ___.“',fa:'«Ich kaufe den Tisch. — Ich kaufe ___.»'},
   a:'ihn',o:['es','sie','ihm'],
   ex:{en:'<i>der Tisch</i> is masculine and the direct object → <b>ihn</b>. <i>ihm</i> is dative („to him“), not accusative.',
       fa:'<i>der Tisch</i> مذکر و مفعول مستقیم است → <b>ihn</b>. <i>ihm</i> حالت داتیو است، نه آکوزاتیو.'}}
 ]},

{id:'pronomen-dat',ic:'🎁',lv:2,sk:'Cases',
 title:{en:'Dative pronouns & their order',fa:'ضمایر داتیو و ترتیبشان'},
 sub:{en:'mir, dir, ihm, ihr, uns, euch, ihnen',fa:'mir، dir، ihm، ihr، uns، euch، ihnen'},
 blocks:[
  {type:'text',md:{en:'The <b>Dativ</b> pronoun is the one that <i>benefits</i>: the person you give something <b>to</b>, help, thank, or write <b>to</b>. In English this is often marked with „to“ or „for“ — in German the pronoun itself changes shape.',
        fa:'ضمیر <b>داتیو</b> همان است که <i>بهره می‌برد</i>: کسی که چیزی <b>به</b> او می‌دهی، کمکش می‌کنی، از او تشکر می‌کنی یا <b>به</b> او می‌نویسی. در انگلیسی اغلب با «to» یا «for» نشان داده می‌شود — در آلمانی خود ضمیر عوض می‌شود.'}},
  {type:'table',head:['','Akkusativ','Dativ'],rows:[
   ['ich','mich','*mir'],['du','dich','*dir'],['er','ihn','*ihm'],
   ['sie (she)','sie','*ihr'],['es','es','*ihm'],['wir','uns','uns'],
   ['ihr','euch','euch'],['sie (they)','sie','*ihnen'],['Sie','Sie','*Ihnen']],
   cap:{en:'uns and euch do double duty — one form for both cases',fa:'uns و euch دوکاره‌اند — یک شکل برای هر دو حالت'}},
  {type:'examples',items:[
   {de:'Kannst du mir helfen?',en:'Can you help me?',say:'Kannst du mir helfen?'},
   {de:'Wie geht es dir?',en:'How are you?',say:'Wie geht es dir?'},
   {de:'Das Auto gehört ihm.',en:'The car belongs to him.',say:'Das Auto gehört ihm.'},
   {de:'Das Buch gefällt ihr sehr.',en:'She likes the book a lot.',say:'Das Buch gefällt ihr sehr.'},
   {de:'Ich schreibe ihnen eine E-Mail.',en:'I’m writing them an e-mail.',say:'Ich schreibe ihnen eine E-Mail.'},
   {de:'Gefällt es Ihnen hier?',en:'Do you like it here? (formal)',say:'Gefällt es Ihnen hier?'}]},
  {type:'warn',md:{en:'A group of very common verbs takes the <b>Dativ</b> where English feels like a direct object: <b class="deword">helfen</b>, <b class="deword">danken</b>, <b class="deword">gehören</b>, <b class="deword">gefallen</b>, <b class="deword">passen</b>, <b class="deword">schmecken</b>, <b class="deword">antworten</b>. So „Ich helfe <b>dir</b>“ — never „ich helfe dich“. And the fixed phrase is „Wie geht es <b>dir</b>?“, never „dich“.',
        fa:'گروهی از فعل‌های پرکاربرد <b>داتیو</b> می‌گیرند، جایی که در انگلیسی مفعول مستقیم حس می‌شود: <b class="deword">helfen</b>، <b class="deword">danken</b>، <b class="deword">gehören</b>، <b class="deword">gefallen</b>، <b class="deword">passen</b>، <b class="deword">schmecken</b>، <b class="deword">antworten</b>. پس «Ich helfe <b>dir</b>» — هرگز «dich». و عبارت ثابت «Wie geht es <b>dir</b>?» است.'}},
  {type:'text',md:{en:'When a sentence has <b>both</b> objects („I give <i>the child</i> <i>the ball</i>“), German has a clear order. The logic is simple: <b>short and known comes first</b>. Pronouns are short and known, so they push forward.',
        fa:'وقتی جمله <b>هر دو</b> مفعول را دارد («من به بچه توپ را می‌دهم»)، آلمانی ترتیب روشنی دارد. منطقش ساده است: <b>کوتاه و شناخته‌شده اول می‌آید</b>. ضمیرها کوتاه و شناخته‌شده‌اند، پس جلو می‌افتند.'}},
  {type:'steps',items:[
   {en:'Two <b>nouns</b> → Dativ first: „Ich gebe <b>dem Kind</b> <b>den Ball</b>.“',fa:'دو <b>اسم</b> → اول داتیو: «Ich gebe <b>dem Kind</b> <b>den Ball</b>.»'},
   {en:'One <b>pronoun</b> + one noun → the pronoun first, whatever its case: „Ich gebe <b>ihm</b> den Ball.“ / „Ich gebe <b>ihn</b> dem Kind.“',fa:'یک <b>ضمیر</b> + یک اسم → ضمیر اول، هر حالتی که داشته باشد: «Ich gebe <b>ihm</b> den Ball.» / «Ich gebe <b>ihn</b> dem Kind.»'},
   {en:'Two <b>pronouns</b> → Akkusativ first, Dativ second: „Ich gebe <b>ihn</b> <b>ihm</b>.“ / „Ich gebe <b>es</b> <b>dir</b>.“',fa:'دو <b>ضمیر</b> → اول آکوزاتیو، بعد داتیو: «Ich gebe <b>es</b> <b>dir</b>.»'}]},
  {type:'tip',md:{en:'Hook for the forms: a Dativ ending almost always contains an <b>m</b> or an <b>r</b>. de<b>m</b> → ih<b>m</b>, de<b>r</b> → ih<b>r</b>, mi<b>r</b>, di<b>r</b>, ihne<b>n</b> (plural -n). Hear an m or r, think Dativ.',
        fa:'قلاب شکل‌ها: پایانهٔ داتیو تقریباً همیشه <b>m</b> یا <b>r</b> دارد. de<b>m</b> → ih<b>m</b>، de<b>r</b> → ih<b>r</b>، mi<b>r</b>، di<b>r</b>. اگر m یا r شنیدی، به داتیو فکر کن.'}},
  {type:'dialog',lines:[
   {who:'A',de:'Entschuldigung, können Sie mir helfen?',en:'Excuse me, can you help me?'},
   {who:'B',de:'Natürlich. Was brauchen Sie?',en:'Of course. What do you need?'},
   {who:'A',de:'Gehört dieser Schlüssel Ihnen?',en:'Does this key belong to you?'},
   {who:'B',de:'Nein, aber ich gebe ihn dem Portier.',en:'No, but I’ll give it to the porter.'}]},
  {type:'quiz',q:{en:'„Hast du das Geld? — Ja, ich gebe ___ morgen.“ (it, to you)',fa:'«Hast du das Geld? — Ja, ich gebe ___ morgen.» (آن را، به تو)'},
   a:'es dir',o:['dir es','dich es','es dich'],
   ex:{en:'Two pronouns → <b>Akkusativ first</b>: „ich gebe <b>es dir</b>“. With a noun it would flip: „ich gebe es <b>dem Kind</b>“.',
       fa:'دو ضمیر → <b>اول آکوزاتیو</b>: «ich gebe <b>es dir</b>». با اسم برعکس می‌شود: «ich gebe es <b>dem Kind</b>».'}}
 ]},

{id:'verben-stamm',ic:'🔀',lv:2,sk:'Verbs',
 title:{en:'Verbs that change their vowel',fa:'فعل‌هایی که مصوتشان عوض می‌شود'},
 sub:{en:'sprechen → du sprichst',fa:'sprechen → du sprichst'},
 blocks:[
  {type:'text',md:{en:'Regular verbs keep their stem and just add endings. A sizeable group of common verbs also <b>changes the stem vowel</b> — but only in <b>two</b> of the six forms: <b>du</b> and <b>er/sie/es</b>. Everything else stays normal.',
        fa:'فعل‌های باقاعده بن خود را نگه می‌دارند و فقط پایانه می‌گیرند. گروه بزرگی از فعل‌های پرکاربرد <b>مصوت بن</b> را هم عوض می‌کنند — اما تنها در <b>دو</b> شکل از شش شکل: <b>du</b> و <b>er/sie/es</b>. بقیه عادی می‌مانند.'}},
  {type:'table',head:['','sprechen (e→i)','lesen (e→ie)','fahren (a→ä)'],rows:[
   ['ich','spreche','lese','fahre'],
   ['du','*sprichst','*liest','*fährst'],
   ['er/sie/es','*spricht','*liest','*fährt'],
   ['wir','sprechen','lesen','fahren'],
   ['ihr','sprecht','lest','fahrt'],
   ['sie/Sie','sprechen','lesen','fahren']],
   cap:{en:'the change lives in the middle two rows only',fa:'تغییر فقط در دو سطر میانی است'}},
  {type:'table',head:['Change','Verbs','du-form','er-form'],rows:[
   ['e → i','sprechen','sprichst','spricht'],
   ['e → i','geben','gibst','gibt'],
   ['e → i','helfen','hilfst','hilft'],
   ['e → i','essen','*isst','*isst'],
   ['e → i','nehmen','*nimmst','*nimmt'],
   ['e → ie','lesen','liest','liest'],
   ['e → ie','sehen','siehst','sieht'],
   ['a → ä','fahren','fährst','fährt'],
   ['a → ä','schlafen','schläfst','schläft'],
   ['a → ä','tragen','trägst','trägt'],
   ['au → äu','laufen','läufst','läuft']],
   cap:{en:'nehmen and essen also lose or double a consonant — learn those two by heart',fa:'nehmen و essen صامت را هم حذف یا دوبرابر می‌کنند — این دو را حفظ کن'}},
  {type:'warn',md:{en:'<b>wir, ihr and sie never change.</b> „wir <s>sprichen</s>“ and „ihr <s>fährt</s>“ are classic beginner errors — the correct forms are <b>wir sprechen</b> and <b>ihr fahrt</b>. If you have changed the vowel, check that the subject really is <i>du</i> or <i>er/sie/es</i>.',
        fa:'<b>wir، ihr و sie هرگز عوض نمی‌شوند.</b> «wir <s>sprichen</s>» و «ihr <s>fährt</s>» خطای کلاسیک مبتدی‌اند — درستش <b>wir sprechen</b> و <b>ihr fahrt</b> است. اگر مصوت را عوض کردی، مطمئن شو فاعل واقعاً <i>du</i> یا <i>er/sie/es</i> است.'}},
  {type:'examples',items:[
   {de:'Du sprichst schon gut Deutsch.',en:'You already speak good German.',say:'Du sprichst schon gut Deutsch.'},
   {de:'Er nimmt den Bus um acht.',en:'He takes the bus at eight.',say:'Er nimmt den Bus um acht.'},
   {de:'Sie liest jeden Abend.',en:'She reads every evening.',say:'Sie liest jeden Abend.'},
   {de:'Fährst du mit dem Zug?',en:'Are you going by train?',say:'Fährst du mit dem Zug?'},
   {de:'Das Kind schläft noch.',en:'The child is still sleeping.',say:'Das Kind schläft noch.'},
   {de:'Ihr sprecht sehr schnell.',en:'You (all) speak very fast.',say:'Ihr sprecht sehr schnell.'}]},
  {type:'tip',md:{en:'Bonus: the <b>du</b>-imperative inherits the <b>e→i / e→ie</b> change but <i>not</i> the Umlaut: <b>Sprich!</b> <b>Nimm!</b> <b>Lies!</b> <b>Gib mir das!</b> — yet <b>Fahr langsam!</b> and <b>Schlaf gut!</b> keep the plain a.',
        fa:'نکتهٔ اضافه: امر <b>du</b> تغییر <b>e→i / e→ie</b> را به ارث می‌برد اما اوملاوت را <i>نه</i>: <b>Sprich!</b> <b>Nimm!</b> <b>Lies!</b> — ولی <b>Fahr langsam!</b> و <b>Schlaf gut!</b> همان a را نگه می‌دارند.'}},
  {type:'quiz',q:{en:'„Was ___ du zum Frühstück?“ (essen)',fa:'«Was ___ du zum Frühstück?» (essen)'},
   a:'isst',o:['esst','issest','esse'],
   ex:{en:'<i>essen</i> changes e→i, and the stem already ends in -ss, so du and er/sie/es share one form: <b>isst</b>. („esst“ is the ihr-form.)',
       fa:'<i>essen</i> تغییر e→i دارد و بن به -ss ختم می‌شود، پس du و er/sie/es یک شکل دارند: <b>isst</b>. («esst» شکل ihr است.)'}}
 ]},

{id:'verbposition',ic:'2️⃣',lv:2,sk:'Sentences',
 title:{en:'The verb sits in position 2',fa:'فعل در جایگاه دوم می‌نشیند'},
 sub:{en:'What „position 1“ really means',fa:'«جایگاه ۱» واقعاً چیست'},
 blocks:[
  {type:'text',md:{en:'In a German statement the <b>conjugated verb is the second element</b> — not the second word, the second <i>element</i>. Why does German allow the rest to move around? Because cases (den, dem, einen…) already show who does what. Word order is therefore free for emphasis, and the verb in slot 2 is the fixed anchor that keeps the sentence readable.',
        fa:'در جملهٔ خبری آلمانی، <b>فعل صرف‌شده عنصر دوم است</b> — نه کلمهٔ دوم، بلکه <i>عنصر</i> دوم. چرا بقیه می‌توانند جابه‌جا شوند؟ چون حالت‌ها (den، dem، einen…) از قبل نشان می‌دهند کی چه‌کاری می‌کند. پس ترتیب کلمات برای تأکید آزاد است و فعل در جایگاه ۲ لنگر ثابت جمله است.'}},
  {type:'table',head:['Position 1','Verb','Rest'],rows:[
   ['Ich','*lerne','heute Deutsch.'],
   ['Heute','*lerne','ich Deutsch.'],
   ['Deutsch','*lerne','ich heute.'],
   ['Jeden Montagabend','*lerne','ich Deutsch.'],
   ['Mit meinem Bruder','*lerne','ich Deutsch.'],
   ['In der Bibliothek','*lerne','ich Deutsch.']],
   cap:{en:'five different openings — the verb never moves',fa:'پنج آغاز مختلف — فعل هرگز جابه‌جا نمی‌شود'}},
  {type:'rule',md:{en:'<b>Position 1 holds exactly one element — and an element can be many words.</b> „Jeden Montagabend“ is four syllables and three words, but one single piece of information, so it fills slot 1 completely. The verb comes next, and the subject follows the verb. That swap is called <b>inversion</b>.',
        fa:'<b>جایگاه ۱ دقیقاً یک عنصر دارد — و یک عنصر می‌تواند چند کلمه باشد.</b> «Jeden Montagabend» سه کلمه است اما یک تکه اطلاعات، پس تمام جایگاه ۱ را پر می‌کند. بعد فعل می‌آید و فاعل پس از فعل. به این جابه‌جایی <b>وارونگی</b> می‌گویند.'}},
  {type:'warn',md:{en:'The number-one word-order mistake: „<s>Heute ich lerne Deutsch.</s>“ English keeps the subject in front („Today I learn…“), German cannot. The moment something else takes slot 1, the subject must move <b>behind</b> the verb: „Heute <b>lerne ich</b> Deutsch.“ Say it as one unit — <i>lerne ich</i>, <i>fahre ich</i>, <i>habe ich</i> — and it will start to feel automatic.',
        fa:'اشتباه شمارهٔ یک: «<s>Heute ich lerne Deutsch.</s>» انگلیسی فاعل را جلو نگه می‌دارد، آلمانی نمی‌تواند. تا چیز دیگری جایگاه ۱ را بگیرد، فاعل باید <b>پس از</b> فعل برود: «Heute <b>lerne ich</b> Deutsch.» این را یک واحد بگو — <i>lerne ich</i>، <i>fahre ich</i> — تا خودکار شود.'}},
  {type:'examples',items:[
   {de:'Am Wochenende arbeite ich nicht.',en:'At the weekend I don’t work.',say:'Am Wochenende arbeite ich nicht.'},
   {de:'Nach der Arbeit gehe ich einkaufen.',en:'After work I go shopping.',say:'Nach der Arbeit gehe ich einkaufen.'},
   {de:'In Berlin wohnen viele Studenten.',en:'Many students live in Berlin.',say:'In Berlin wohnen viele Studenten.'},
   {de:'Morgen fährt mein Bruder nach Hamburg.',en:'Tomorrow my brother is going to Hamburg.',say:'Morgen fährt mein Bruder nach Hamburg.'},
   {de:'Leider habe ich keine Zeit.',en:'Unfortunately I have no time.',say:'Leider habe ich keine Zeit.'}]},
  {type:'steps',items:[
   {en:'Find the conjugated verb (the one that agrees with the subject).',fa:'فعل صرف‌شده را پیدا کن (همان که با فاعل مطابقت دارد).'},
   {en:'Count the elements before it. There must be exactly <b>one</b>.',fa:'عنصرهای قبل از آن را بشمار. باید دقیقاً <b>یکی</b> باشد.'},
   {en:'If there are two, move the subject behind the verb.',fa:'اگر دو تا بود، فاعل را پس از فعل ببر.'},
   {en:'Questions are the exception: yes/no questions put the verb in slot 1, W-questions give slot 1 to the W-word.',fa:'سؤال‌ها استثنا هستند: سؤال بله/خیر فعل را در جایگاه ۱ می‌گذارد و سؤال W جایگاه ۱ را به کلمهٔ پرسشی می‌دهد.'}]},
  {type:'tip',md:{en:'After the verb, the normal order is <b>time → manner → place</b>: „Ich fahre <i>morgen</i> <i>mit dem Zug</i> <i>nach Köln</i>.“ It is a default, not a law — but it always sounds right.',
        fa:'پس از فعل، ترتیب عادی <b>زمان ← حالت ← مکان</b> است: «Ich fahre <i>morgen</i> <i>mit dem Zug</i> <i>nach Köln</i>.» یک پیش‌فرض است، نه قانون — اما همیشه درست به گوش می‌آید.'}},
  {type:'quiz',q:{en:'Which sentence is correct?',fa:'کدام جمله درست است؟'},
   a:'Morgen fahre ich nach Wien.',o:['Morgen ich fahre nach Wien.','Morgen ich nach Wien fahre.','Fahre morgen ich nach Wien.'],
   ex:{en:'„Morgen“ takes slot 1, so the verb <b>fahre</b> must come straight after it and the subject <i>ich</i> follows the verb.',
       fa:'«Morgen» جایگاه ۱ را می‌گیرد، پس فعل <b>fahre</b> باید بلافاصله بعد از آن بیاید و فاعل <i>ich</i> پس از فعل.'}}
 ]},

{id:'esgibt',ic:'🫳',lv:2,sk:'Sentences',
 title:{en:'es gibt — there is / there are',fa:'es gibt — وجود دارد'},
 sub:{en:'One form for everything',fa:'یک شکل برای همه‌چیز'},
 blocks:[
  {type:'text',md:{en:'To say that something <b>exists</b> somewhere, German uses the fixed phrase <b class="deword">es gibt</b> — literally „it gives“. It never changes: not for plural, not for people, not for things. „Es gibt einen Park.“ „Es gibt zwei Kinos.“',
        fa:'برای گفتن اینکه چیزی جایی <b>وجود دارد</b>، آلمانی عبارت ثابت <b class="deword">es gibt</b> را به کار می‌برد — تحت‌اللفظی «می‌دهد». هرگز تغییر نمی‌کند: نه برای جمع، نه برای افراد، نه برای اشیا.'}},
  {type:'rule',md:{en:'What follows <b>es gibt</b> is a direct object, so it stands in the <b>Akkusativ</b>: „Es gibt <b>einen</b> Bahnhof“ (der Bahnhof), „eine Apotheke“, „ein Kino“, „<b>keine</b> Probleme“.',
        fa:'آنچه پس از <b>es gibt</b> می‌آید مفعول مستقیم است، پس در حالت <b>آکوزاتیو</b> قرار می‌گیرد: «Es gibt <b>einen</b> Bahnhof»، «eine Apotheke»، «ein Kino»، «<b>keine</b> Probleme».'}},
  {type:'table',head:['Gender','Akkusativ after es gibt','Example'],rows:[
   ['der Bahnhof','*einen','Es gibt einen Bahnhof.'],
   ['die Apotheke','eine','Es gibt eine Apotheke.'],
   ['das Kino','ein','Es gibt ein Kino.'],
   ['Plural','viele / zwei / keine','Es gibt viele Cafés.']]},
  {type:'examples',items:[
   {de:'Hier gibt es einen Park.',en:'There is a park here.',say:'Hier gibt es einen Park.'},
   {de:'Gibt es hier ein Café?',en:'Is there a café here?',say:'Gibt es hier ein Café?'},
   {de:'In der Stadt gibt es zwei Kinos.',en:'There are two cinemas in town.',say:'In der Stadt gibt es zwei Kinos.'},
   {de:'Es gibt keine Milch mehr.',en:'There is no milk left.',say:'Es gibt keine Milch mehr.'},
   {de:'Was gibt es heute zum Mittagessen?',en:'What is there for lunch today?',say:'Was gibt es heute zum Mittagessen?'}]},
  {type:'warn',md:{en:'Two traps. First: German does <b>not</b> make this plural. English switches „there is → there are“; German keeps <b>es gibt</b> for one thing and for a thousand. „<s>Es sind</s> zwei Kinos“ is wrong. Second: do not forget the Akkusativ — „<s>Es gibt ein Bahnhof</s>“ should be <b>einen</b> Bahnhof.',
        fa:'دو تله. اول: آلمانی این را جمع نمی‌کند. انگلیسی «there is → there are» می‌شود؛ آلمانی برای یکی و برای هزار تا همان <b>es gibt</b> را نگه می‌دارد. «<s>Es sind</s> zwei Kinos» غلط است. دوم: آکوزاتیو را فراموش نکن — «<s>ein Bahnhof</s>» باید <b>einen</b> Bahnhof باشد.'}},
  {type:'contrast',cols:[
   {t:'es gibt = it exists',md:{en:'Existence, availability, what is on offer.<br>„In meinem Dorf <b>gibt es</b> keinen Supermarkt.“<br>„<b>Gibt es</b> noch Karten?“<br>„Was <b>gibt es</b> im Kino?“',
       fa:'وجود، در دسترس بودن، آنچه عرضه می‌شود.<br>«<b>Gibt es</b> noch Karten?»'}},
   {t:'das ist / da ist',md:{en:'Identifying or pointing at something already present.<br>„<b>Das ist</b> meine Schwester.“ (who it is)<br>„<b>Da ist</b> der Bus!“ (look, there)<br>„Die Schlüssel <b>sind</b> auf dem Tisch.“ (where they are)',
       fa:'معرفی یا اشاره به چیزی که حاضر است.<br>«<b>Das ist</b> meine Schwester.» · «<b>Da ist</b> der Bus!»'}}]},
  {type:'dialog',lines:[
   {who:'A',de:'Entschuldigung, gibt es hier in der Nähe eine Apotheke?',en:'Excuse me, is there a pharmacy nearby?'},
   {who:'B',de:'Ja, es gibt eine am Bahnhof. Da ist auch ein Supermarkt.',en:'Yes, there is one at the station. There is a supermarket there too.'},
   {who:'A',de:'Und gibt es einen Geldautomaten?',en:'And is there a cash machine?'},
   {who:'B',de:'Leider nicht. Aber das ist kein Problem — ich habe Bargeld.',en:'Unfortunately not. But that’s no problem — I have cash.'}]},
  {type:'quiz',q:{en:'„In meiner Stadt ___ es drei Schwimmbäder.“',fa:'«In meiner Stadt ___ es drei Schwimmbäder.»'},
   a:'gibt',o:['geben','sind','ist'],
   ex:{en:'<b>es gibt</b> is frozen in the singular, even with a plural noun: „es gibt drei Schwimmbäder“.',
       fa:'<b>es gibt</b> در مفرد ثابت است، حتی با اسم جمع: «es gibt drei Schwimmbäder».'}}
 ]},

{id:'moechten',ic:'🙏',lv:2,sk:'Verbs',
 title:{en:'möchten — the polite „I’d like“',fa:'möchten — «می‌خواهم» مؤدبانه'},
 sub:{en:'möchten vs wollen',fa:'möchten در برابر wollen'},
 blocks:[
  {type:'text',md:{en:'<b class="deword">möchten</b> means „would like“. It is the single most useful verb for a beginner in a German-speaking country: you order with it, you ask with it, you book with it. Its blunt cousin <b class="deword">wollen</b> means „want“ — correct, but direct enough to sound demanding in a shop or café.',
        fa:'<b class="deword">möchten</b> یعنی «می‌خواهم / مایلم». برای یک مبتدی در کشور آلمانی‌زبان کاربردی‌ترین فعل است: با آن سفارش می‌دهی، می‌پرسی و رزرو می‌کنی. پسرعموی صریحش <b class="deword">wollen</b> یعنی «می‌خواهم» — درست است، اما در مغازه یا کافه کمی طلبکارانه به گوش می‌آید.'}},
  {type:'table',head:['','möchten (would like)','wollen (want)'],rows:[
   ['ich','*möchte','*will'],['du','möchtest','willst'],
   ['er/sie/es','*möchte','*will'],['wir','möchten','wollen'],
   ['ihr','möchtet','wollt'],['sie/Sie','möchten','wollen']],
   cap:{en:'ich and er/sie/es are identical — no -t on either',fa:'ich و er/sie/es یکسان‌اند — هیچ‌کدام -t نمی‌گیرند'}},
  {type:'rule',md:{en:'möchten behaves like a modal verb: it takes slot 2 and sends the main verb, as a plain <b>infinitive, to the very end</b> — with <b>no „zu“</b>. „Ich <b>möchte</b> ein Zimmer <b>reservieren</b>.“ With a simple noun object it can also stand alone: „Ich <b>möchte</b> einen Kaffee.“',
        fa:'möchten مثل فعل وجهی رفتار می‌کند: جایگاه ۲ را می‌گیرد و فعل اصلی را به‌صورت <b>مصدر به آخر جمله</b> می‌فرستد — <b>بدون «zu»</b>. «Ich <b>möchte</b> ein Zimmer <b>reservieren</b>.» با مفعول اسمی ساده هم می‌تواند تنها بیاید: «Ich <b>möchte</b> einen Kaffee.»'}},
  {type:'examples',items:[
   {de:'Ich möchte einen Kaffee, bitte.',en:'I’d like a coffee, please.',say:'Ich möchte einen Kaffee, bitte.'},
   {de:'Ich möchte bitte bezahlen.',en:'I’d like to pay, please.',say:'Ich möchte bitte bezahlen.'},
   {de:'Möchtest du mitkommen?',en:'Would you like to come along?',say:'Möchtest du mitkommen?'},
   {de:'Was möchten Sie trinken?',en:'What would you like to drink?',say:'Was möchten Sie trinken?'},
   {de:'Wir möchten die Rechnung, bitte.',en:'We’d like the bill, please.',say:'Wir möchten die Rechnung, bitte.'},
   {de:'Er will heute nicht arbeiten.',en:'He doesn’t want to work today.',say:'Er will heute nicht arbeiten.'}]},
  {type:'warn',md:{en:'Three traps. (1) No -t after ich: „<s>ich möchtet</s>“ — it is <b>ich möchte</b>. (2) No „zu“: „<s>Ich möchte zu bezahlen</s>“ — it is <b>Ich möchte bezahlen</b>. (3) In a shop, „<b>Ich will</b> einen Kaffee“ is grammatically fine but socially rough; say <b>Ich möchte</b> or <b>Ich hätte gern</b> instead.',
        fa:'سه تله. (۱) بعد از ich هیچ -t نمی‌آید: <b>ich möchte</b>. (۲) هیچ «zu»: <b>Ich möchte bezahlen</b>. (۳) در مغازه «Ich will einen Kaffee» دستوری درست است اما بی‌ادبانه به گوش می‌آید؛ به‌جایش <b>Ich möchte</b> یا <b>Ich hätte gern</b> بگو.'}},
  {type:'contrast',cols:[
   {t:'möchten — polite wish',md:{en:'Here and now, in a shop, at a counter, in a café.<br>„<b>Ich möchte</b> zwei Brötchen.“<br>„<b>Möchten Sie</b> noch etwas?“<br>Soft, friendly, never wrong.',
       fa:'همین‌جا و همین‌حالا، در مغازه، باجه یا کافه.<br>«<b>Ich möchte</b> zwei Brötchen.» نرم، دوستانه و هرگز نادرست.'}},
   {t:'wollen — firm intention',md:{en:'A plan or a will, often with a reason.<br>„Ich <b>will</b> Arzt werden.“ (ambition)<br>„Sie <b>will</b> das nicht machen.“ (refusal)<br>Strong; keep it for intentions, not orders in a café.',
       fa:'قصد یا ارادهٔ محکم.<br>«Ich <b>will</b> Arzt werden.» قوی است؛ برای نیت‌ها نگهش دار، نه برای سفارش در کافه.'}}]},
  {type:'dialog',lines:[
   {who:'A',de:'Guten Tag! Was möchten Sie?',en:'Hello! What would you like?'},
   {who:'B',de:'Ich möchte einen Kaffee und ein Stück Kuchen, bitte.',en:'I’d like a coffee and a piece of cake, please.'},
   {who:'A',de:'Möchten Sie den Kuchen mit Sahne?',en:'Would you like the cake with cream?'},
   {who:'B',de:'Nein, danke. Und ich möchte bitte gleich bezahlen.',en:'No thanks. And I’d like to pay right away, please.'}]},
  {type:'tip',md:{en:'Two phrases that make you sound instantly polite: <b>„Ich möchte …, bitte.“</b> and <b>„Ich hätte gern …“</b>. Add <b>bitte</b> and you can order anything in Germany without ever using <i>wollen</i>.',
        fa:'دو عبارت که فوراً مؤدبانه‌ات می‌کنند: <b>«Ich möchte …, bitte.»</b> و <b>«Ich hätte gern …»</b>. با افزودن <b>bitte</b> می‌توانی هر چیزی را بدون استفاده از <i>wollen</i> سفارش دهی.'}}
 ]},

{id:'modal-basis',ic:'🔧',lv:2,sk:'Verbs',
 title:{en:'können, müssen, dürfen',fa:'können، müssen، dürfen'},
 sub:{en:'The modal bracket',fa:'قلاب فعل وجهی'},
 blocks:[
  {type:'text',md:{en:'A <b>modal verb</b> says <i>how</i> you relate to an action: you are able to (<b class="deword">können</b>), you have to (<b class="deword">müssen</b>), you are allowed to (<b class="deword">dürfen</b>). The modal is the one that gets conjugated; the real action verb stays an <b>infinitive</b> and goes to the end of the sentence.',
        fa:'<b>فعل وجهی</b> می‌گوید <i>چگونه</i> با یک کنش نسبت داری: می‌توانی (<b class="deword">können</b>)، باید (<b class="deword">müssen</b>)، اجازه داری (<b class="deword">dürfen</b>). فعل وجهی صرف می‌شود؛ فعل اصلی <b>مصدر</b> می‌ماند و به آخر جمله می‌رود.'}},
  {type:'table',head:['','können (can)','müssen (must)','dürfen (may)'],rows:[
   ['ich','*kann','*muss','*darf'],
   ['du','kannst','musst','darfst'],
   ['er/sie/es','*kann','*muss','*darf'],
   ['wir','können','müssen','dürfen'],
   ['ihr','könnt','müsst','dürft'],
   ['sie/Sie','können','müssen','dürfen']],
   cap:{en:'ich = er/sie/es, and the vowel changes in the singular',fa:'ich = er/sie/es، و مصوت در مفرد عوض می‌شود'}},
  {type:'rule',md:{en:'The two verbs form a <b>bracket</b> (<i>Satzklammer</i>) around the middle of the sentence: the modal opens it in position 2, the infinitive closes it at the very end. Everything else — objects, times, places, <i>nicht</i> — lives inside.',
        fa:'دو فعل یک <b>قلاب</b> (<i>Satzklammer</i>) دور وسط جمله می‌سازند: فعل وجهی آن را در جایگاه ۲ باز می‌کند و مصدر در آخر می‌بندد. هر چیز دیگر — مفعول، زمان، مکان، <i>nicht</i> — داخل آن می‌ماند.'}},
  {type:'table',head:['Pos. 1','Modal','Middle','Infinitive'],rows:[
   ['Ich','*kann','heute leider nicht','*kommen.'],
   ['Wir','*müssen','um sieben Uhr','*aufstehen.'],
   ['Hier','*darf','man nicht','*parken.'],
   ['Morgen','*kann','ich dir','*helfen.']],
   cap:{en:'the two halves of the verb hold the sentence together',fa:'دو نیمهٔ فعل جمله را به هم نگه می‌دارند'}},
  {type:'examples',items:[
   {de:'Ich kann gut schwimmen.',en:'I can swim well.',say:'Ich kann gut schwimmen.'},
   {de:'Du musst noch die Hausaufgaben machen.',en:'You still have to do the homework.',say:'Du musst noch die Hausaufgaben machen.'},
   {de:'Darf ich das Fenster öffnen?',en:'May I open the window?',say:'Darf ich das Fenster öffnen?'},
   {de:'Hier darf man nicht rauchen.',en:'Smoking is not allowed here.',say:'Hier darf man nicht rauchen.'},
   {de:'Können Sie mir bitte helfen?',en:'Could you help me, please?',say:'Können Sie mir bitte helfen?'},
   {de:'Wir müssen morgen früh aufstehen.',en:'We have to get up early tomorrow.',say:'Wir müssen morgen früh aufstehen.'}]},
  {type:'warn',md:{en:'The big one: <b>nicht müssen ≠ must not</b>. „Du <b>musst nicht</b> kommen“ means <i>you don’t have to</i> come — you are free. „You must not come“ is „Du <b>darfst nicht</b> kommen.“ Mixing these up can turn a kind permission into a ban, or a ban into an invitation.',
        fa:'مهم‌ترین نکته: <b>nicht müssen ≠ نباید</b>. «Du <b>musst nicht</b> kommen» یعنی <i>لازم نیست</i> بیایی — آزادی. «نباید بیایی» می‌شود «Du <b>darfst nicht</b> kommen.» قاطی کردن این دو می‌تواند اجازه را به ممنوعیت تبدیل کند.'}},
  {type:'tip',md:{en:'No „zu“ with modals, ever: „Ich muss <b>gehen</b>“, not „ich muss <s>zu gehen</s>“. And a separable verb stays glued together at the end: „Ich muss <b>aufstehen</b>“ — one word.',
        fa:'با افعال وجهی هرگز «zu» نمی‌آید: «Ich muss <b>gehen</b>». و فعل جداشدنی در آخر یکپارچه می‌ماند: «Ich muss <b>aufstehen</b>» — یک کلمه.'}},
  {type:'quiz',q:{en:'„Du ___ nicht kommen — ich schaffe das allein.“ (you are free to stay away)',fa:'«Du ___ nicht kommen — ich schaffe das allein.» (لازم نیست بیایی)'},
   a:'musst',o:['darfst','müsst','kannst'],
   ex:{en:'<b>nicht müssen</b> = no obligation. „darfst nicht“ would be a prohibition („you are not allowed to come“).',
       fa:'<b>nicht müssen</b> = بدون الزام. «darfst nicht» ممنوعیت می‌شود («اجازه نداری بیایی»).'}}
 ]},

{id:'trennbar-basis',ic:'✂️',lv:2,sk:'Verbs',
 title:{en:'Separable verbs',fa:'فعل‌های جداشدنی'},
 sub:{en:'aufstehen → Ich stehe … auf',fa:'aufstehen → Ich stehe … auf'},
 blocks:[
  {type:'text',md:{en:'Many German verbs are built from a small word plus a verb: <b>auf</b> + stehen = <b class="deword">aufstehen</b> (to get up). As soon as you conjugate such a verb in a simple sentence, the little word — the <b>prefix</b> — breaks off and runs to the <b>end</b> of the clause: „Ich <b>stehe</b> um sieben Uhr <b>auf</b>.“',
        fa:'بسیاری از فعل‌های آلمانی از یک کلمهٔ کوچک به‌علاوهٔ فعل ساخته می‌شوند: <b>auf</b> + stehen = <b class="deword">aufstehen</b> (بیدار شدن). به‌محض صرف چنین فعلی در جملهٔ ساده، آن کلمهٔ کوچک — <b>پیشوند</b> — جدا می‌شود و به <b>آخر</b> جمله می‌دود: «Ich <b>stehe</b> um sieben Uhr <b>auf</b>.»'}},
  {type:'table',head:['Infinitive','Meaning','In a sentence'],rows:[
   ['aufstehen','to get up','Ich stehe früh *auf.'],
   ['einkaufen','to shop','Wir kaufen im Supermarkt *ein.'],
   ['anrufen','to phone','Ich rufe dich später *an.'],
   ['mitkommen','to come along','Kommst du *mit?'],
   ['fernsehen','to watch TV','Abends sieht er *fern.'],
   ['anfangen','to start','Der Film fängt um acht *an.']],
   cap:{en:'the prefix always lands last, after objects, times and places',fa:'پیشوند همیشه آخر می‌نشیند، بعد از مفعول، زمان و مکان'}},
  {type:'rule',md:{en:'The prefix only leaves when the verb is <b>conjugated</b>. If the verb stays an <b>infinitive</b> — after a modal, after <i>möchten</i>, or in a list — it remains in one piece: „Ich muss früh <b>aufstehen</b>.“ „Ich möchte dich <b>anrufen</b>.“',
        fa:'پیشوند فقط وقتی جدا می‌شود که فعل <b>صرف</b> شود. اگر فعل <b>مصدر</b> بماند — بعد از فعل وجهی، بعد از <i>möchten</i>، یا در فهرست — یکپارچه می‌ماند: «Ich muss früh <b>aufstehen</b>.»'}},
  {type:'steps',items:[
   {en:'Split the verb in your head: <b>auf</b> | <b>stehen</b>.',fa:'فعل را در ذهنت جدا کن: <b>auf</b> | <b>stehen</b>.'},
   {en:'Conjugate only the second part: ich steh<b>e</b>, du steh<b>st</b>, er steh<b>t</b>.',fa:'فقط بخش دوم را صرف کن: ich steh<b>e</b>، du steh<b>st</b>، er steh<b>t</b>.'},
   {en:'Put that verb in position 2 and build the rest of the sentence.',fa:'آن فعل را در جایگاه ۲ بگذار و بقیهٔ جمله را بساز.'},
   {en:'Drop the prefix at the very end: „Ich stehe um sieben Uhr <b>auf</b>.“',fa:'پیشوند را در انتها بگذار: «Ich stehe um sieben Uhr <b>auf</b>.»'}]},
  {type:'warn',md:{en:'Not every prefix separates. The unstressed ones — <b>be-, ge-, er-, ver-, ent-, emp-, miss-</b> — never leave the verb: „Ich <b>verstehe</b> dich“, never „<s>ich stehe dich ver</s>“. „Ich <b>bezahle</b>“, „Ich <b>erkläre</b>“, „Ich <b>gefalle</b>“. The sound test works: if you naturally stress the prefix (<b>ÁUF</b>stehen, <b>ÁN</b>rufen) it separates; if the stress falls on the verb (ver<b>STÉ</b>hen) it does not.',
        fa:'هر پیشوندی جدا نمی‌شود. پیشوندهای بی‌تکیه — <b>be-، ge-، er-، ver-، ent-، emp-، miss-</b> — هرگز از فعل جدا نمی‌شوند: «Ich <b>verstehe</b> dich»، نه «<s>ich stehe dich ver</s>». آزمون صدا: اگر تکیه روی پیشوند باشد (<b>ÁUF</b>stehen) جدا می‌شود؛ اگر روی فعل باشد (ver<b>STÉ</b>hen) نه.'}},
  {type:'dialog',lines:[
   {who:'A',de:'Wann stehst du am Samstag auf?',en:'What time do you get up on Saturday?'},
   {who:'B',de:'Spät! Aber zuerst rufe ich meine Mutter an.',en:'Late! But first I’ll call my mother.'},
   {who:'A',de:'Kaufst du danach ein? Ich komme gern mit.',en:'Are you going shopping afterwards? I’d like to come along.'},
   {who:'B',de:'Gern. Der Markt fängt um neun an.',en:'Sure. The market starts at nine.'}]},
  {type:'quiz',q:{en:'„Wann ___ der Film an?“ (anfangen)',fa:'«Wann ___ der Film an?» (anfangen)'},
   a:'fängt',o:['anfängt','fangt','fängst'],
   ex:{en:'anfangen separates <i>and</i> changes its stem vowel a→ä in the er-form: „Wann <b>fängt</b> der Film <b>an</b>?“',
       fa:'anfangen هم جدا می‌شود <i>و هم</i> در شکل er مصوت بن را a→ä عوض می‌کند: «Wann <b>fängt</b> der Film <b>an</b>?»'}}
 ]},

{id:'ortsprep',ic:'📍',lv:2,sk:'Prepositions',
 title:{en:'Saying where something is',fa:'گفتن اینکه چیزی کجاست'},
 sub:{en:'Wo? → Dativ',fa:'Wo؟ ← داتیو'},
 blocks:[
  {type:'text',md:{en:'To answer <b>Wo?</b> („where?“) German uses nine little words: <b>in, an, auf, unter, über, neben, vor, hinter, zwischen</b>. For a <b>location</b> — nothing moving, nothing going anywhere — they all take the <b>Dativ</b>. That is the whole A1 rule.',
        fa:'برای پاسخ به <b>Wo?</b> («کجا؟») آلمانی نه کلمهٔ کوچک دارد: <b>in، an، auf، unter، über، neben، vor، hinter، zwischen</b>. برای <b>مکان</b> — وقتی چیزی حرکت نمی‌کند — همه <b>داتیو</b> می‌گیرند. همین کل قاعدهٔ A1 است.'}},
  {type:'table',head:['','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','der','die','das','die'],
   ['Dativ (Wo?)','*dem','*der','*dem','*den + -n']],
   cap:{en:'feminine der in the Dativ is not masculine — in der Küche',fa:'der مؤنث در داتیو مذکر نیست — in der Küche'}},
  {type:'examples',items:[
   {de:'Das Buch liegt auf dem Tisch.',en:'The book is on the table.',say:'Das Buch liegt auf dem Tisch.'},
   {de:'Ich bin in der Küche.',en:'I’m in the kitchen.',say:'Ich bin in der Küche.'},
   {de:'Die Katze sitzt unter dem Stuhl.',en:'The cat is sitting under the chair.',say:'Die Katze sitzt unter dem Stuhl.'},
   {de:'Das Bild hängt an der Wand.',en:'The picture is hanging on the wall.',say:'Das Bild hängt an der Wand.'},
   {de:'Das Auto steht vor dem Haus.',en:'The car is parked in front of the house.',say:'Das Auto steht vor dem Haus.'},
   {de:'Die Apotheke ist zwischen der Bäckerei und dem Kino.',en:'The pharmacy is between the bakery and the cinema.',say:'Die Apotheke ist zwischen der Bäckerei und dem Kino.'}]},
  {type:'rule',md:{en:'German melts some of these together. Learn the short forms — natives use nothing else: <b>in dem → im</b>, <b>an dem → am</b>, <b>bei dem → beim</b>, <b>zu dem → zum</b>, <b>zu der → zur</b>. „<b>im</b> Garten“, „<b>am</b> Bahnhof“, „<b>beim</b> Arzt“.',
        fa:'آلمانی بعضی از این‌ها را در هم ذوب می‌کند. شکل کوتاه را یاد بگیر، چون آلمانی‌زبان‌ها فقط همین را می‌گویند: <b>in dem → im</b>، <b>an dem → am</b>، <b>bei dem → beim</b>، <b>zu dem → zum</b>، <b>zu der → zur</b>.'}},
  {type:'contrast',cols:[
   {t:'auf vs. an',md:{en:'<b>auf</b> = on top of a surface.<br>„auf <b>dem</b> Tisch“, „auf <b>dem</b> Boden“, „auf <b>der</b> Straße“.<br><br><b>an</b> = touching a vertical thing, or at the edge of something.<br>„an <b>der</b> Wand“, „am Fenster“, „am See“, „am Bahnhof“.',
       fa:'<b>auf</b> = روی یک سطح.<br>«auf dem Tisch»<br><br><b>an</b> = چسبیده به چیزی عمودی یا کنار چیزی.<br>«an der Wand»، «am Fenster»، «am See».'}},
   {t:'in vs. bei',md:{en:'<b>in</b> = inside a space.<br>„in <b>der</b> Schule“, „in <b>dem</b> → im Büro“, „in <b>der</b> Stadt“.<br><br><b>bei</b> = at a person’s place or workplace.<br>„bei <b>meiner</b> Mutter“, „beim Arzt“, „bei Siemens“.',
       fa:'<b>in</b> = درون یک فضا.<br>«in der Schule»، «im Büro»<br><br><b>bei</b> = نزد کسی یا در محل کار.<br>«beim Arzt»، «bei meiner Mutter».'}}]},
  {type:'warn',md:{en:'English uses „in“ for both „I am <i>in</i> the kitchen“ and „I go <i>in</i>to the kitchen“, so learners copy one German form for both. German does not: location takes <b>Dativ</b> („Ich bin <b>in der</b> Küche“), movement takes Akkusativ („Ich gehe <b>in die</b> Küche“). For now use one safe test: <b>if nothing travels, use the Dativ.</b>',
        fa:'انگلیسی برای «در آشپزخانه هستم» و «به آشپزخانه می‌روم» هر دو از «in» استفاده می‌کند، پس زبان‌آموز یک شکل آلمانی را برای هر دو به کار می‌برد. آلمانی این‌طور نیست: مکان <b>داتیو</b> («Ich bin <b>in der</b> Küche»)، حرکت آکوزاتیو («Ich gehe <b>in die</b> Küche»). فعلاً یک آزمون مطمئن: <b>اگر چیزی جابه‌جا نمی‌شود، داتیو.</b>'}},
  {type:'tip',md:{en:'The three „standing“ verbs almost always come with a Dativ location: <b>liegen</b> (lie), <b>stehen</b> (stand), <b>sitzen</b> (sit) — plus <b>sein</b> and <b>wohnen</b>. If your sentence has one of those, reach for dem/der straight away.',
        fa:'سه فعل «ایستا» تقریباً همیشه با مکان داتیو می‌آیند: <b>liegen</b>، <b>stehen</b>، <b>sitzen</b> — به‌علاوهٔ <b>sein</b> و <b>wohnen</b>. اگر جمله‌ات یکی از این‌ها را دارد، بی‌درنگ dem/der بردار.'}},
  {type:'quiz',q:{en:'„Die Kinder spielen ___ Garten.“ (der Garten, nobody is going anywhere)',fa:'«Die Kinder spielen ___ Garten.» (der Garten، کسی جایی نمی‌رود)'},
   a:'im',o:['in','in den','ins'],
   ex:{en:'Location → Dativ → <i>in dem</i>, and <i>in dem</i> always shortens to <b>im</b>. „in den Garten“ would mean they are walking into it.',
       fa:'مکان ← داتیو ← <i>in dem</i>، و <i>in dem</i> همیشه به <b>im</b> کوتاه می‌شود. «in den Garten» یعنی دارند داخلش می‌روند.'}}
 ]},

{id:'und-aber',ic:'🔗',lv:2,sk:'Sentences',
 title:{en:'und, aber, oder, denn, sondern',fa:'und، aber، oder، denn، sondern'},
 sub:{en:'The five harmless connectors',fa:'پنج حرف ربط بی‌خطر'},
 blocks:[
  {type:'text',md:{en:'These five words join two <b>full main clauses</b> — and they are the easiest connectors in German, because they <b>change nothing</b>. They sit in front of the second clause in what grammarians call <b>position 0</b>, so the second clause still begins normally: subject, then verb in slot 2.',
        fa:'این پنج کلمه دو <b>جملهٔ اصلی کامل</b> را به هم وصل می‌کنند — و آسان‌ترین حروف ربط آلمانی‌اند، چون <b>هیچ‌چیز را عوض نمی‌کنند</b>. در آنچه دستوردان‌ها <b>جایگاه ۰</b> می‌نامند می‌نشینند، پس جملهٔ دوم عادی شروع می‌شود: فاعل، بعد فعل در جایگاه ۲.'}},
  {type:'table',head:['Word','Meaning','Example'],rows:[
   ['und','and','Ich lerne Deutsch *und ich arbeite in Wien.'],
   ['aber','but','Ich bin müde, *aber ich arbeite weiter.'],
   ['oder','or','Trinkst du Tee *oder trinkst du Kaffee?'],
   ['denn','because / for','Wir bleiben zu Hause, *denn es regnet.'],
   ['sondern','but rather','Das ist kein Tee, *sondern Kaffee.']],
   cap:{en:'in every example the second clause keeps its normal order',fa:'در هر مثال، جملهٔ دوم ترتیب عادی‌اش را نگه می‌دارد'}},
  {type:'rule',md:{en:'Count the connector as <b>nothing at all</b> when you look for position 1. „… <b>denn</b> <b>ich</b> habe keine Zeit“: <i>denn</i> is position 0, <i>ich</i> is position 1, <i>habe</i> is position 2. The sentence looks exactly as it would standing alone.',
        fa:'وقتی دنبال جایگاه ۱ هستی، حرف ربط را <b>هیچ</b> حساب کن. «… <b>denn</b> <b>ich</b> habe keine Zeit»: <i>denn</i> جایگاه ۰، <i>ich</i> جایگاه ۱، <i>habe</i> جایگاه ۲. جمله دقیقاً مثل حالت تنهایی‌اش است.'}},
  {type:'examples',items:[
   {de:'Ich bin müde, aber ich arbeite weiter.',en:'I’m tired, but I keep working.',say:'Ich bin müde, aber ich arbeite weiter.'},
   {de:'Wir bleiben zu Hause, denn es regnet.',en:'We’re staying home, because it’s raining.',say:'Wir bleiben zu Hause, denn es regnet.'},
   {de:'Möchtest du Tee oder Kaffee?',en:'Would you like tea or coffee?',say:'Möchtest du Tee oder Kaffee?'},
   {de:'Das ist nicht mein Mantel, sondern deiner.',en:'That isn’t my coat, it’s yours.',say:'Das ist nicht mein Mantel, sondern deiner.'},
   {de:'Ich komme aus dem Iran und ich wohne in Berlin.',en:'I’m from Iran and I live in Berlin.',say:'Ich komme aus dem Iran und ich wohne in Berlin.'}]},
  {type:'rule',md:{en:'<b>sondern</b> is special: it only works after a <b>negative</b> („not X, but rather Y“). „Ich trinke <b>keinen</b> Kaffee, <b>sondern</b> Tee.“ With no negative in the first half, use <b>aber</b>.',
        fa:'<b>sondern</b> ویژه است: فقط بعد از یک <b>منفی</b> کار می‌کند («نه X، بلکه Y»). «Ich trinke <b>keinen</b> Kaffee, <b>sondern</b> Tee.» اگر نیمهٔ اول منفی نیست، <b>aber</b> به کار ببر.'}},
  {type:'warn',md:{en:'Do not confuse <b>denn</b> with <b>weil</b>. They mean the same thing, but <b>weil</b> throws the verb to the <b>end</b>: „…, <b>denn</b> es <b>regnet</b>“ / „…, <b>weil</b> es <b>regnet</b>“ look alike — add an object and the difference appears: „…, <b>denn</b> ich <b>habe</b> Zeit“ versus „…, <b>weil</b> ich Zeit <b>habe</b>“. If you want the easy life at A1, use <b>denn</b>.',
        fa:'<b>denn</b> را با <b>weil</b> اشتباه نگیر. معنایشان یکی است، اما <b>weil</b> فعل را به <b>آخر</b> می‌اندازد: «…, <b>denn</b> ich <b>habe</b> Zeit» در برابر «…, <b>weil</b> ich Zeit <b>habe</b>». اگر در A1 زندگی راحتی می‌خواهی، <b>denn</b> به کار ببر.'}},
  {type:'tip',md:{en:'Commas: always put one before <b>aber, denn, sondern</b>. Before <b>und</b> and <b>oder</b> joining two main clauses the comma is optional — leaving it out is never wrong.',
        fa:'ویرگول: پیش از <b>aber، denn، sondern</b> همیشه ویرگول بگذار. پیش از <b>und</b> و <b>oder</b> که دو جملهٔ اصلی را وصل می‌کنند اختیاری است — نگذاشتنش هرگز غلط نیست.'}},
  {type:'quiz',q:{en:'„Ich habe kein Auto, ___ ein Fahrrad.“',fa:'«Ich habe kein Auto, ___ ein Fahrrad.»'},
   a:'sondern',o:['aber','denn','oder'],
   ex:{en:'The first half is negative (<i>kein</i> Auto), and the second half corrects it → <b>sondern</b>. <i>aber</i> would need a contrast, not a correction.',
       fa:'نیمهٔ اول منفی است (<i>kein</i> Auto) و نیمهٔ دوم آن را اصلاح می‌کند → <b>sondern</b>.'}}
 ]},

{id:'laender',ic:'🌍',lv:2,sk:'Vocabulary',
 title:{en:'Countries, nationalities, languages',fa:'کشورها، ملیت‌ها، زبان‌ها'},
 sub:{en:'in · nach · aus',fa:'in · nach · aus'},
 blocks:[
  {type:'text',md:{en:'„Where are you from? Where do you live? Where are you going?“ — the first three questions you will ever be asked. German answers them with three prepositions: <b>aus</b> (origin), <b>in</b> (location), <b>nach</b> (destination).',
        fa:'«از کجایی؟ کجا زندگی می‌کنی؟ کجا می‌روی؟» — سه پرسش اولی که از تو می‌پرسند. آلمانی با سه حرف اضافه جواب می‌دهد: <b>aus</b> (اصل)، <b>in</b> (مکان)، <b>nach</b> (مقصد).'}},
  {type:'table',head:['Question','Preposition','Example'],rows:[
   ['Woher? (from where)','*aus','Ich komme *aus Deutschland.'],
   ['Wo? (where)','*in','Ich wohne *in Deutschland.'],
   ['Wohin? (where to)','*nach','Ich fahre *nach Deutschland.']],
   cap:{en:'this works for all article-less countries and for all cities',fa:'این برای همهٔ کشورهای بدون حرف تعریف و همهٔ شهرها کار می‌کند'}},
  {type:'text',md:{en:'Most countries carry <b>no article</b>: Deutschland, Österreich, Italien, Spanien, Frankreich, England, Polen, Japan, Indien. A small group does carry one — and those few change the pattern completely, so learn them as a list.',
        fa:'بیشتر کشورها <b>حرف تعریف ندارند</b>: Deutschland، Österreich، Italien، Spanien، Frankreich، England، Polen، Japan، Indien. گروه کوچکی حرف تعریف دارند — و همین چند تا الگو را کامل عوض می‌کنند، پس فهرست‌وار یادشان بگیر.'}},
  {type:'table',head:['Country','Woher? aus','Wo? in','Wohin? in'],rows:[
   ['die Türkei','*aus der Türkei','*in der Türkei','*in die Türkei'],
   ['die Schweiz','aus der Schweiz','in der Schweiz','in die Schweiz'],
   ['der Iran','aus dem Iran','im Iran','in den Iran'],
   ['der Irak','aus dem Irak','im Irak','in den Irak'],
   ['die USA (pl)','aus den USA','in den USA','in die USA'],
   ['die Niederlande (pl)','aus den Niederlanden','in den Niederlanden','in die Niederlande']],
   cap:{en:'with an article the destination uses in + Akkusativ, never nach',fa:'با حرف تعریف، مقصد با in + آکوزاتیو می‌آید، هرگز nach'}},
  {type:'table',head:['Country','Man / Woman','Language'],rows:[
   ['Deutschland','Deutscher / Deutsche','Deutsch'],
   ['Österreich','Österreicher / Österreicherin','Deutsch'],
   ['Italien','Italiener / Italienerin','Italienisch'],
   ['Spanien','Spanier / Spanierin','Spanisch'],
   ['Frankreich','Franzose / Französin','Französisch'],
   ['England','Engländer / Engländerin','Englisch'],
   ['die Türkei','Türke / Türkin','Türkisch'],
   ['der Iran','Iraner / Iranerin','Persisch']],
   cap:{en:'the feminine form adds -in; languages are capitalised nouns',fa:'شکل مؤنث -in می‌گیرد؛ نام زبان‌ها اسم‌اند و با حرف بزرگ'}},
  {type:'examples',items:[
   {de:'Ich komme aus dem Iran und wohne in Hamburg.',en:'I’m from Iran and live in Hamburg.',say:'Ich komme aus dem Iran und wohne in Hamburg.'},
   {de:'Im Sommer fahren wir nach Italien.',en:'In summer we’re going to Italy.',say:'Im Sommer fahren wir nach Italien.'},
   {de:'Meine Freundin fliegt in die Türkei.',en:'My girlfriend is flying to Turkey.',say:'Meine Freundin fliegt in die Türkei.'},
   {de:'Sie kommt aus der Schweiz.',en:'She comes from Switzerland.',say:'Sie kommt aus der Schweiz.'},
   {de:'Ich bin Iranerin und ich spreche Persisch und Deutsch.',en:'I’m Iranian (f) and I speak Persian and German.',say:'Ich bin Iranerin und ich spreche Persisch und Deutsch.'}]},
  {type:'warn',md:{en:'<b>nach</b> only works with article-less countries and with cities: „nach Italien“, „nach Berlin“. With the article-countries you must say „<b>in die</b> Türkei“, „<b>in den</b> Iran“, „<b>in die</b> Schweiz“ — „<s>nach die Türkei</s>“ is one of the most audible beginner errors. And nationalities and languages are <b>nouns</b>, so they get a capital: „Ich spreche <b>Deutsch</b>“ — while the lowercase <i>deutsch</i> is the adjective: „ein <b>deutsches</b> Auto“.',
        fa:'<b>nach</b> فقط با کشورهای بدون حرف تعریف و با شهرها کار می‌کند: «nach Italien»، «nach Berlin». با کشورهای دارای حرف تعریف باید بگویی «<b>in die</b> Türkei»، «<b>in den</b> Iran». «<s>nach die Türkei</s>» از شنیدنی‌ترین خطاهای مبتدی است. ملیت و زبان <b>اسم</b> هستند و حرف بزرگ می‌گیرند: «Ich spreche <b>Deutsch</b>» — اما <i>deutsch</i> کوچک صفت است: «ein <b>deutsches</b> Auto».'}},
  {type:'tip',md:{en:'Professions and nationalities take <b>no article</b> after <i>sein</i> (see the ein/kein lesson): „Ich bin <b>Iraner</b>.“ „Sie ist <b>Österreicherin</b>.“ Germany is the odd one out — a German says „Ich bin <b>Deutscher</b>“ (m) or „Ich bin <b>Deutsche</b>“ (f), because that word behaves like an adjective.',
        fa:'شغل و ملیت بعد از <i>sein</i> <b>حرف تعریف نمی‌گیرند</b>: «Ich bin <b>Iraner</b>.» «Sie ist <b>Österreicherin</b>.» آلمان استثناست — یک آلمانی می‌گوید «Ich bin <b>Deutscher</b>» (مرد) یا «Ich bin <b>Deutsche</b>» (زن)، چون این کلمه مثل صفت رفتار می‌کند.'}}
 ]},

{id:'plural-basis',ic:'🧺',lv:2,sk:'Vocabulary',
 title:{en:'Making nouns plural',fa:'جمع بستن اسم‌ها'},
 sub:{en:'Five patterns, one article',fa:'پنج الگو، یک حرف تعریف'},
 blocks:[
  {type:'text',md:{en:'English has one plural („-s“) and a handful of oddities. German has <b>five</b> patterns and no way to predict which one a noun takes. The one piece of good news: in the plural, the article is always <b>die</b>, for all three genders.',
        fa:'انگلیسی یک جمع («-s») و چند استثنا دارد. آلمانی <b>پنج</b> الگو دارد و راهی برای پیش‌بینی نیست که اسم کدام را می‌گیرد. یک خبر خوب: در جمع، حرف تعریف همیشه <b>die</b> است، برای هر سه جنس.'}},
  {type:'table',head:['Pattern','Singular','Plural','Note'],rows:[
   ['-e','der Hund','die Hund*e','many masculine nouns'],
   ['-e + Umlaut','der Stuhl','die St*ühle','short masculine nouns'],
   ['-er','das Kind','die Kind*er','often neuter'],
   ['-er + Umlaut','das Buch','die B*ücher','der Mann → die Männer'],
   ['-(e)n','die Frau','die Frau*en','almost all feminine nouns'],
   ['-s','das Auto','die Auto*s','loanwords: Hotels, Handys'],
   ['— (nothing)','der Lehrer','die Lehrer','-er, -el, -en, -chen'],
   ['— + Umlaut','der Vater','die V*äter','only the vowel moves']],
   cap:{en:'five patterns, each with an Umlaut variant',fa:'پنج الگو، هرکدام با یک نوع اوملاوتی'}},
  {type:'rule',md:{en:'The tendencies worth trusting: <b>feminine → -(e)n</b> (die Zeitung → die Zeitungen, die Lampe → die Lampen). Nouns in <b>-chen, -lein, -er, -el, -en</b> add <b>nothing</b> (das Mädchen → die Mädchen). Words borrowed from English or French take <b>-s</b> (das Handy → die Handys).',
        fa:'گرایش‌هایی که ارزش اعتماد دارند: <b>مؤنث ← ‎-(e)n</b> (die Zeitung → die Zeitungen). اسم‌های <b>-chen، -lein، -er، -el، -en</b> <b>هیچ‌چیز</b> اضافه نمی‌کنند (das Mädchen → die Mädchen). واژه‌های قرضی <b>-s</b> می‌گیرند (das Handy → die Handys).'}},
  {type:'examples',items:[
   {de:'ein Kind → zwei Kinder',en:'one child → two children',say:'zwei Kinder'},
   {de:'ein Buch → drei Bücher',en:'one book → three books',say:'drei Bücher'},
   {de:'eine Zeitung → vier Zeitungen',en:'one newspaper → four newspapers',say:'vier Zeitungen'},
   {de:'ein Auto → viele Autos',en:'one car → many cars',say:'viele Autos'},
   {de:'ein Lehrer → zwei Lehrer',en:'one teacher → two teachers',say:'zwei Lehrer'},
   {de:'eine Lehrerin → zwei Lehrerinnen',en:'one female teacher → two female teachers',say:'zwei Lehrerinnen'}]},
  {type:'warn',md:{en:'There is no default <b>-s</b> in German. „zwei <s>Hunds</s>“, „drei <s>Buchs</s>“, „vier <s>Kinds</s>“ are all wrong — the -s plural is reserved for foreign words. And don’t let the plural article fool you: <b>die</b> Hunde is still a masculine noun; <i>die</i> here means „plural“, not „feminine“.',
        fa:'در آلمانی <b>-s</b> پیش‌فرض وجود ندارد. «zwei <s>Hunds</s>»، «drei <s>Buchs</s>» همه غلط‌اند — جمع با -s برای واژه‌های بیگانه است. و حرف تعریف جمع گولت نزند: <b>die</b> Hunde باز هم اسمی مذکر است؛ <i>die</i> اینجا یعنی «جمع»، نه «مؤنث».'}},
  {type:'rule',md:{en:'One extra ending to know now, because you will need it with prepositions: in the <b>Dativ plural</b> the noun adds an <b>-n</b> (unless the plural already ends in -n or -s). „mit den <b>Kindern</b>“, „mit zwei <b>Freunden</b>“, „in den <b>Bergen</b>“ — but „mit den Autos“.',
        fa:'یک پایانهٔ اضافی که از الان لازم است، چون با حروف اضافه به کارت می‌آید: در <b>داتیو جمع</b> اسم یک <b>-n</b> می‌گیرد (مگر جمع از قبل به -n یا -s ختم شود). «mit den <b>Kindern</b>»، «mit zwei <b>Freunden</b>» — اما «mit den Autos».'}},
  {type:'tip',md:{en:'Write new nouns the way dictionaries do, with gender <i>and</i> plural in one line: <b>der Tisch, -e</b> · <b>das Buch, ¨-er</b> · <b>die Frau, -en</b> · <b>der Lehrer, -</b>. Three seconds when you learn the word saves you a guess every time you use it.',
        fa:'اسم‌های تازه را مثل فرهنگ‌نامه‌ها بنویس، با جنس <i>و</i> جمع در یک خط: <b>der Tisch, -e</b> · <b>das Buch, ¨-er</b> · <b>die Frau, -en</b> · <b>der Lehrer, -</b>. سه ثانیه هنگام یادگیری، هر بار یک حدس را از تو می‌گیرد.'}},
  {type:'quiz',q:{en:'„Im Zimmer stehen vier ___.“ (der Stuhl)',fa:'«Im Zimmer stehen vier ___.» (der Stuhl)'},
   a:'Stühle',o:['Stuhle','Stuhls','Stühlen'],
   ex:{en:'<i>der Stuhl</i> takes -e plus an Umlaut → <b>die Stühle</b>. „Stühlen“ is the Dativ plural („mit den Stühlen“).',
       fa:'<i>der Stuhl</i> پایانهٔ -e به‌علاوهٔ اوملاوت می‌گیرد → <b>die Stühle</b>. «Stühlen» داتیو جمع است.'}}
 ]},

{id:'datum-wochentag',ic:'📅',lv:2,sk:'Numbers',
 title:{en:'Days, months, seasons',fa:'روزها، ماه‌ها، فصل‌ها'},
 sub:{en:'am Montag · im Januar · im Sommer',fa:'am Montag · im Januar · im Sommer'},
 blocks:[
  {type:'text',md:{en:'Good news first: <b>every</b> day, month and season is masculine — <b class="deword">der</b> Montag, <b class="deword">der</b> Januar, <b class="deword">der</b> Sommer. That means you only ever need the masculine Dativ form <i>dem</i>, which is why these expressions all come out as <b>am</b> or <b>im</b>.',
        fa:'اول خبر خوب: <b>همهٔ</b> روزها، ماه‌ها و فصل‌ها مذکرند — <b class="deword">der</b> Montag، <b class="deword">der</b> Januar، <b class="deword">der</b> Sommer. یعنی همیشه فقط به شکل داتیو مذکر <i>dem</i> نیاز داری و همین است که این عبارت‌ها <b>am</b> یا <b>im</b> می‌شوند.'}},
  {type:'table',head:['Day','English','Day','English'],rows:[
   ['Montag','Monday','Freitag','Friday'],
   ['Dienstag','Tuesday','Samstag','Saturday'],
   ['Mittwoch','Wednesday','Sonntag','Sunday'],
   ['Donnerstag','Thursday','das Wochenende','the weekend']]},
  {type:'table',head:['Months','','',''],rows:[
   ['Januar','April','Juli','Oktober'],
   ['Februar','Mai','August','November'],
   ['März','Juni','September','Dezember']],
   cap:{en:'spoken German often says „Jänner“ in Austria for Januar',fa:'در اتریش برای ژانویه اغلب «Jänner» گفته می‌شود'}},
  {type:'rule',md:{en:'<b>am</b> + day (= an dem) · <b>im</b> + month or season (= in dem) · <b>am</b> + part of the day. „<b>am</b> Montag“, „<b>am</b> Wochenende“, „<b>im</b> Januar“, „<b>im</b> Sommer“, „<b>am</b> Morgen“, „<b>am</b> Abend“.',
        fa:'<b>am</b> + روز (= an dem) · <b>im</b> + ماه یا فصل (= in dem) · <b>am</b> + بخشی از روز. «<b>am</b> Montag»، «<b>im</b> Januar»، «<b>im</b> Sommer»، «<b>am</b> Abend».'}},
  {type:'table',head:['Phrase','Means','Note'],rows:[
   ['*am Montag','on Monday','an dem Montag'],
   ['*am Wochenende','at the weekend','das Wochenende'],
   ['*im Januar','in January','in dem Januar'],
   ['*im Sommer','in summer','der Sommer'],
   ['*am Abend','in the evening','der Abend'],
   ['*in der Nacht','at night','die Nacht — the one feminine!']],
   cap:{en:'die Nacht is the single exception in this family',fa:'die Nacht تنها استثنای این خانواده است'}},
  {type:'examples',items:[
   {de:'Am Montag habe ich einen Deutschkurs.',en:'On Monday I have a German class.',say:'Am Montag habe ich einen Deutschkurs.'},
   {de:'Im Januar ist es sehr kalt.',en:'In January it’s very cold.',say:'Im Januar ist es sehr kalt.'},
   {de:'Im Sommer fahren wir nach Spanien.',en:'In summer we go to Spain.',say:'Im Sommer fahren wir nach Spanien.'},
   {de:'Am Wochenende schlafe ich lange.',en:'At the weekend I sleep in.',say:'Am Wochenende schlafe ich lange.'},
   {de:'Heute ist Dienstag, morgen ist Mittwoch.',en:'Today is Tuesday, tomorrow is Wednesday.',say:'Heute ist Dienstag, morgen ist Mittwoch.'},
   {de:'Mein Geburtstag ist am dritten Mai.',en:'My birthday is on the third of May.',say:'Mein Geburtstag ist am dritten Mai.'}]},
  {type:'warn',md:{en:'Two things trip people up. (1) When you only <b>name</b> the day, drop everything: „<b>Heute ist Montag</b>“ — not „am Montag“ and not „der Montag ist heute“. The preposition appears only when you say <i>when</i> something happens. (2) It is <b>am</b> Montag, never „<s>an Montag</s>“ or „<s>in Montag</s>“ — the article is baked into <i>am</i>.',
        fa:'دو چیز مردم را می‌لنگاند. (۱) وقتی فقط روز را <b>نام می‌بری</b>، همه‌چیز را بردار: «<b>Heute ist Montag</b>» — نه «am Montag». حرف اضافه فقط وقتی می‌آید که می‌گویی <i>چه زمانی</i> کاری رخ می‌دهد. (۲) همیشه <b>am</b> Montag است، هرگز «<s>an Montag</s>» — حرف تعریف داخل <i>am</i> پخته شده است.'}},
  {type:'tip',md:{en:'For habits, add <b>-s</b> and keep it lowercase: <b>montags</b> („on Mondays“), <b>abends</b> („in the evenings“), <b>sonntags</b>, <b>morgens</b>. „<b>Montags</b> gehe ich schwimmen“ = every Monday. These are adverbs, which is why they stay small.',
        fa:'برای عادت‌ها یک <b>-s</b> اضافه کن و کوچک نگه دار: <b>montags</b> («دوشنبه‌ها»)، <b>abends</b> («شب‌ها»)، <b>sonntags</b>. «<b>Montags</b> gehe ich schwimmen» = هر دوشنبه. این‌ها قید هستند و همین دلیل کوچک ماندنشان است.'}}
 ]},

{id:'adjektiv-praedikativ',ic:'🎨',lv:2,sk:'Adjectives',
 title:{en:'Adjectives with no ending',fa:'صفت‌های بدون پایانه'},
 sub:{en:'The easy half of German adjectives',fa:'نیمهٔ آسان صفت‌های آلمانی'},
 blocks:[
  {type:'text',md:{en:'You have probably heard that German adjective endings are a nightmare. Here is the half nobody warns you about: when the adjective comes <b>after</b> <b class="deword">sein</b>, <b class="deword">werden</b> or <b class="deword">bleiben</b>, it takes <b>no ending at all</b>. Not one. For every gender, every number.',
        fa:'حتماً شنیده‌ای که پایانه‌های صفت آلمانی کابوس‌اند. این نیمه‌ای است که کسی دربارهٔ آن هشدار نمی‌دهد: وقتی صفت <b>بعد از</b> <b class="deword">sein</b>، <b class="deword">werden</b> یا <b class="deword">bleiben</b> می‌آید، <b>هیچ پایانه‌ای</b> نمی‌گیرد. برای هر جنس و هر شمار.'}},
  {type:'table',head:['Subject','Verb','Adjective'],rows:[
   ['Der Mann','ist','*groß.'],
   ['Die Frau','ist','*groß.'],
   ['Das Kind','ist','*groß.'],
   ['Die Kinder','sind','*groß.'],
   ['Es','wird','*dunkel.'],
   ['Bitte','bleib','*ruhig!']],
   cap:{en:'one single form — groß — covers all of them',fa:'یک شکل واحد — groß — همهٔ این‌ها را پوشش می‌دهد'}},
  {type:'examples',items:[
   {de:'Der Kaffee ist heiß.',en:'The coffee is hot.',say:'Der Kaffee ist heiß.'},
   {de:'Die Suppe ist kalt.',en:'The soup is cold.',say:'Die Suppe ist kalt.'},
   {de:'Das Buch ist interessant.',en:'The book is interesting.',say:'Das Buch ist interessant.'},
   {de:'Die Kinder sind müde.',en:'The children are tired.',say:'Die Kinder sind müde.'},
   {de:'Im Winter wird es früh dunkel.',en:'In winter it gets dark early.',say:'Im Winter wird es früh dunkel.'},
   {de:'Die Wohnung ist klein, aber schön.',en:'The flat is small but lovely.',say:'Die Wohnung ist klein, aber schön.'}]},
  {type:'rule',md:{en:'Endings appear <b>only</b> when the adjective stands <b>in front of</b> its noun. Compare: „Der Kaffee ist <b>heiß</b>“ (after the verb → bare) and „ein <b>heißer</b> Kaffee“ (before the noun → ending). That second half is a later lesson; this half you can use perfectly from today.',
        fa:'پایانه‌ها <b>فقط</b> وقتی ظاهر می‌شوند که صفت <b>پیش از</b> اسمش بیاید. مقایسه کن: «Der Kaffee ist <b>heiß</b>» (بعد از فعل ← بدون پایانه) و «ein <b>heißer</b> Kaffee» (پیش از اسم ← با پایانه). نیمهٔ دوم درس بعدی است؛ این نیمه را از امروز می‌توانی بی‌نقص به کار ببری.'}},
  {type:'contrast',cols:[
   {t:'After the verb → no ending',md:{en:'„Das Haus ist <b>alt</b>.“<br>„Die Häuser sind <b>alt</b>.“<br>„Das Essen war <b>gut</b>.“<br>„Sie wird <b>müde</b>.“<br><br>Always the dictionary form.',
       fa:'«Das Haus ist <b>alt</b>.»<br>«Die Häuser sind <b>alt</b>.»<br>همیشه شکل فرهنگ‌نامه‌ای.'}},
   {t:'Before the noun → ending',md:{en:'„ein <b>altes</b> Haus“<br>„die <b>alten</b> Häuser“<br>„<b>gutes</b> Essen“<br>„eine <b>müde</b> Frau“<br><br>Endings depend on gender, case and article.',
       fa:'«ein <b>altes</b> Haus»<br>«die <b>alten</b> Häuser»<br>پایانه به جنس، حالت و حرف تعریف بستگی دارد.'}}]},
  {type:'warn',md:{en:'Once learners meet the ending tables, they start sprinkling endings everywhere: „<s>Die Suppe ist kalte</s>“, „<s>Der Mann ist großer</s>“. Both are wrong — and the second is worse than wrong, because <b>großer</b> would be heard as the comparative „bigger“. After <i>sein/werden/bleiben</i>: hands off the ending.',
        fa:'زبان‌آموزان پس از دیدن جدول پایانه‌ها شروع می‌کنند همه‌جا پایانه بپاشند: «<s>Die Suppe ist kalte</s>»، «<s>Der Mann ist großer</s>». هر دو غلط‌اند — و دومی بدتر است، چون <b>großer</b> به‌معنای «بزرگ‌تر» شنیده می‌شود. بعد از <i>sein/werden/bleiben</i>: دست به پایانه نزن.'}},
  {type:'tip',md:{en:'Bonus: <b>adverbs have no ending either</b>. German uses the plain adjective where English adds „-ly“: „Er fährt <b>schnell</b>“ (he drives fast/quickly), „Sie spricht <b>gut</b> Deutsch“, „Bitte sprich <b>langsam</b>“. One more place you simply cannot go wrong.',
        fa:'نکتهٔ اضافه: <b>قیدها هم پایانه ندارند</b>. آلمانی همان صفت ساده را به کار می‌برد، جایی که انگلیسی «-ly» اضافه می‌کند: «Er fährt <b>schnell</b>»، «Bitte sprich <b>langsam</b>». یک جای دیگر که اصلاً نمی‌توانی اشتباه کنی.'}},
  {type:'quiz',q:{en:'„Die Suppe ist ___.“',fa:'«Die Suppe ist ___.»'},
   a:'kalt',o:['kalte','kalten','kaltes'],
   ex:{en:'After <i>ist</i> the adjective is bare: <b>kalt</b>. „die kalte Suppe“ only takes an ending because there the adjective sits before the noun.',
       fa:'بعد از <i>ist</i> صفت بدون پایانه است: <b>kalt</b>. «die kalte Suppe» پایانه می‌گیرد چون صفت پیش از اسم است.'}}
 ]},

{id:'du-sie',ic:'🤝',lv:2,sk:'Beginner',
 title:{en:'du or Sie?',fa:'du یا Sie؟'},
 sub:{en:'Choosing how to address people',fa:'انتخاب شکل خطاب'},
 blocks:[
  {type:'text',md:{en:'German has three ways to say „you“, and choosing the wrong one is a social mistake, not a grammatical one. <b class="deword">du</b> = one person you are close to. <b class="deword">ihr</b> = several such people. <b class="deword">Sie</b> = anyone else, one or many, always with a <b>capital S</b>.',
        fa:'آلمانی سه راه برای گفتن «تو/شما» دارد و انتخاب نادرست یک خطای اجتماعی است، نه دستوری. <b class="deword">du</b> = یک نفر که با او نزدیکی. <b class="deword">ihr</b> = چند نفر از همان‌ها. <b class="deword">Sie</b> = هر کس دیگر، یک یا چند نفر، همیشه با <b>S بزرگ</b>.'}},
  {type:'table',head:['Form','Use it for','Example'],rows:[
   ['*du','family, friends, children, classmates, animals','Wie heißt du?'],
   ['*ihr','a group of those','Woher kommt ihr?'],
   ['*Sie','strangers, officials, shops, colleagues, teachers','Wie heißen Sie?']],
   cap:{en:'Sie is one word for one person and for a crowd',fa:'Sie برای یک نفر و برای یک جمع یک کلمه است'}},
  {type:'table',head:['Verb','du','ihr','Sie'],rows:[
   ['kommen','*kommst','*kommt','*kommen'],
   ['heißen','heißt','heißt','heißen'],
   ['haben','hast','habt','haben'],
   ['sein','bist','seid','sind'],
   ['können','kannst','könnt','können'],
   ['possessive','dein / deine','euer / eure','*Ihr / Ihre']],
   cap:{en:'the Sie-form is always the infinitive form (except sein → sind)',fa:'شکل Sie همیشه همان شکل مصدری است (جز sein → sind)'}},
  {type:'examples',items:[
   {de:'Wie heißt du? — Wie heißen Sie?',en:'What’s your name? (informal — formal)',say:'Wie heißt du? Wie heißen Sie?'},
   {de:'Woher kommst du? — Woher kommen Sie?',en:'Where are you from?',say:'Woher kommst du? Woher kommen Sie?'},
   {de:'Hast du Zeit? — Haben Sie Zeit?',en:'Do you have time?',say:'Hast du Zeit? Haben Sie Zeit?'},
   {de:'Ist das dein Auto? — Ist das Ihr Auto?',en:'Is that your car?',say:'Ist das dein Auto? Ist das Ihr Auto?'},
   {de:'Kinder, habt ihr Hunger?',en:'Kids, are you hungry?',say:'Kinder, habt ihr Hunger?'}]},
  {type:'rule',md:{en:'The name you use tells you the form. <b>Herr Müller / Frau Klein + Sie.</b> <b>Anna / Tom + du.</b> They go together like a pair: „Guten Tag, Herr Müller, wie <b>geht es Ihnen</b>?“ versus „Hallo Anna, wie <b>geht es dir</b>?“',
        fa:'نامی که به کار می‌بری شکل را تعیین می‌کند. <b>Herr Müller / Frau Klein + Sie.</b> <b>Anna / Tom + du.</b> مثل یک جفت با هم می‌آیند: «Guten Tag, Herr Müller, wie <b>geht es Ihnen</b>?» در برابر «Hallo Anna, wie <b>geht es dir</b>?»'}},
  {type:'warn',md:{en:'When in doubt, use <b>Sie</b>. Calling an adult stranger <i>du</i> sounds careless or even rude in Germany; using <i>Sie</i> with a friend sounds a little stiff but never offensive. The switch is usually offered out loud — „Wir können uns <b>duzen</b>“ — and then you may change. In writing, never lowercase formal <b>Sie</b>: „wie geht es <b>Ihnen</b>“ is respectful, „wie geht es ihnen“ means „how are <i>they</i>“.',
        fa:'اگر شک داری، <b>Sie</b> به کار ببر. <i>du</i> گفتن به یک بزرگسال غریبه در آلمان بی‌ملاحظه یا حتی بی‌ادب به نظر می‌رسد؛ <i>Sie</i> گفتن به دوست کمی رسمی است اما هرگز توهین نیست. تغییر معمولاً پیشنهاد می‌شود — «Wir können uns <b>duzen</b>». در نوشتار هرگز <b>Sie</b>ی رسمی را کوچک ننویس: «wie geht es <b>Ihnen</b>» محترمانه است، «ihnen» یعنی «حال <i>آن‌ها</i> چطور است».'}},
  {type:'dialog',lines:[
   {who:'A',de:'Guten Tag, mein Name ist Keller. Und wie heißen Sie?',en:'Hello, my name is Keller. And what is your name?'},
   {who:'B',de:'Guten Tag, Frau Keller. Ich bin Amir Sadeghi.',en:'Hello, Mrs Keller. I’m Amir Sadeghi.'},
   {who:'A',de:'Freut mich. Kommen Sie aus dem Iran?',en:'Nice to meet you. Are you from Iran?'},
   {who:'B',de:'Ja, aus Teheran. Wohnen Sie hier in Köln?',en:'Yes, from Tehran. Do you live here in Cologne?'},
   {who:'A',de:'Ja. Und sagen Sie — wir sind Nachbarn, wir können uns duzen!',en:'Yes. And listen — we’re neighbours, let’s use du!'},
   {who:'B',de:'Gern. Woher kommst du denn?',en:'Gladly. So where are you from?'}]},
  {type:'tip',md:{en:'Watch <b>euer</b>: it drops its second <b>e</b> as soon as an ending arrives. „<b>euer</b> Haus“ but „<b>eure</b> Wohnung“, „<b>euren</b> Hund“. The formal possessive is easier — <b>Ihr</b>, <b>Ihre</b>, <b>Ihren</b>, exactly like <i>ihr</i> („her“) but with a capital.',
        fa:'به <b>euer</b> دقت کن: به‌محض آمدن پایانه، <b>e</b>ی دومش را از دست می‌دهد. «<b>euer</b> Haus» اما «<b>eure</b> Wohnung»، «<b>euren</b> Hund». ضمیر ملکی رسمی آسان‌تر است — <b>Ihr</b>، <b>Ihre</b>، <b>Ihren</b>، دقیقاً مثل <i>ihr</i> ولی با حرف بزرگ.'}},
  {type:'quiz',q:{en:'You are in a shop and want to ask the assistant for help. What do you say?',fa:'در مغازه‌ای و می‌خواهی از فروشنده کمک بخواهی. چه می‌گویی؟'},
   a:'Können Sie mir helfen?',o:['Kannst du mir helfen?','Könnt ihr mir helfen?','Kann Sie mir helfen?'],
   ex:{en:'A stranger at work → <b>Sie</b>, and the Sie-form of können is <b>können</b>. „Kann Sie“ mixes the er-form with Sie.',
       fa:'غریبه در محل کار ← <b>Sie</b>، و شکل Sie برای können همان <b>können</b> است. «Kann Sie» شکل er را با Sie قاطی می‌کند.'}}
 ]}

];

window.DRILL_A1=[

/* ---- nomen-gross ---- */
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'Ich lese ein ___.',a:'Buch',o:['buch','Buches','buchs'],
 ex:'Every noun starts with a capital letter: das Buch → ein Buch.',tr:'I’m reading a book.',say:'Ich lese ein Buch.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'Heute kommt mein ___ zu Besuch.',a:'Bruder',o:['bruder','Brüder','brüder'],
 ex:'Capital B — and the singular form, because it is one brother (die Brüder = plural).',tr:'My brother is visiting today.',say:'Heute kommt mein Bruder zu Besuch.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'Das ist ___ Tisch.',a:'der',o:['die','das','dem'],
 ex:'Tisch is masculine → der Tisch. Always learn the article together with the word.',tr:'That is the table.',say:'Das ist der Tisch.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'___ Lampe ist neu.',a:'Die',o:['Der','Das','Den'],
 ex:'Lampe is feminine → die Lampe.',tr:'The lamp is new.',say:'Die Lampe ist neu.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'___ Fenster ist offen.',a:'Das',o:['Der','Die','Dem'],
 ex:'Fenster is neuter → das Fenster.',tr:'The window is open.',say:'Das Fenster ist offen.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'___ Mädchen heißt Anna.',a:'Das',o:['Die','Der','Den'],
 ex:'Mädchen ends in -chen, so it is neuter: das Mädchen. Grammar beats biology.',tr:'The girl is called Anna.',say:'Das Mädchen heißt Anna.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'Am Montag fahre ich nach ___.',a:'Berlin',o:['berlin','Berlins','berlins'],
 ex:'Place names are nouns too and keep their capital letter.',tr:'On Monday I’m travelling to Berlin.',say:'Am Montag fahre ich nach Berlin.'},
{gid:'nomen-gross',lv:1,sk:'Beginner',s:'Ich lerne ___ in der Schule.',a:'Deutsch',o:['deutsch','Deutschen','deutsche'],
 ex:'The language is a noun → Deutsch. Lowercase deutsch is the adjective: ein deutsches Auto.',tr:'I learn German at school.',say:'Ich lerne Deutsch in der Schule.'},

/* ---- gender-regeln ---- */
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Zeitung liegt hier.',a:'Die',o:['Der','Das','Den'],
 ex:'-ung is always feminine → die Zeitung.',tr:'The newspaper is lying here.',say:'Die Zeitung liegt hier.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Mädchen spielt im Garten.',a:'Das',o:['Die','Der','Dem'],
 ex:'-chen makes any noun neuter → das Mädchen.',tr:'The girl is playing in the garden.',say:'Das Mädchen spielt im Garten.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Sommer ist warm.',a:'Der',o:['Die','Das','Den'],
 ex:'Seasons, months, days and weather words are masculine → der Sommer.',tr:'Summer is warm.',say:'Der Sommer ist warm.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Freiheit ist wichtig.',a:'Die',o:['Der','Das','Dem'],
 ex:'-heit → feminine, like -keit and -schaft.',tr:'Freedom is important.',say:'Die Freiheit ist wichtig.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Museum ist heute geschlossen.',a:'Das',o:['Der','Die','Den'],
 ex:'-um → neuter: das Museum, das Zentrum, das Album.',tr:'The museum is closed today.',say:'Das Museum ist heute geschlossen.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'___ Lehrling arbeitet in der Bäckerei.',a:'Der',o:['Die','Das','Dem'],
 ex:'-ling → masculine: der Lehrling, der Frühling.',tr:'The apprentice works in the bakery.',say:'Der Lehrling arbeitet in der Bäckerei.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'Ich kaufe ___ Brötchen.',a:'ein',o:['eine','einen','einem'],
 ex:'-chen → neuter (das Brötchen), and neuter does not change in the accusative → ein Brötchen.',tr:'I’m buying a bread roll.',say:'Ich kaufe ein Brötchen.'},
{gid:'gender-regeln',lv:2,sk:'Articles',s:'Ich bezahle ___ Rechnung.',a:'die',o:['der','das','den'],
 ex:'-ung → die Rechnung, and feminine is unchanged in the accusative.',tr:'I’m paying the bill.',say:'Ich bezahle die Rechnung.'},

/* ---- einkein ---- */
{gid:'einkein',lv:2,sk:'Articles',s:'Das ist ___ Mann.',a:'ein',o:['eine','einen','einem'],
 ex:'der Mann is masculine; after sein the noun is nominative → ein Mann.',tr:'That is a man.',say:'Das ist ein Mann.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Ich habe ___ Schwester.',a:'eine',o:['ein','einen','einem'],
 ex:'die Schwester is feminine, and eine does not change in the accusative.',tr:'I have a sister.',say:'Ich habe eine Schwester.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Er kauft ___ Hund.',a:'einen',o:['ein','eine','einem'],
 ex:'der Hund is the direct object → accusative einen. Masculine always ends in -n here.',tr:'He is buying a dog.',say:'Er kauft einen Hund.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Ich habe ___ Geld.',a:'kein',o:['keine','keinen','nicht'],
 ex:'das Geld is neuter → kein Geld. A noun with no article is negated with kein, not nicht.',tr:'I have no money.',say:'Ich habe kein Geld.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Mein Vater ist ___.',a:'Lehrer',o:['ein Lehrer','einen Lehrer','der Lehrer'],
 ex:'Professions after sein take no article at all: „Mein Vater ist Lehrer.“',tr:'My father is a teacher.',say:'Mein Vater ist Lehrer.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Ich trinke ___ Kaffee.',a:'keinen',o:['kein','keine','nicht'],
 ex:'der Kaffee as a direct object → keinen. kein takes exactly the ein-endings.',tr:'I don’t drink coffee.',say:'Ich trinke keinen Kaffee.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Wir haben ___ Zeit.',a:'keine',o:['kein','keinen','nicht'],
 ex:'die Zeit → keine Zeit. Mass nouns take kein, never „nicht Zeit“.',tr:'We have no time.',say:'Wir haben keine Zeit.'},
{gid:'einkein',lv:2,sk:'Articles',s:'Hier gibt es ___ Parkplätze.',a:'keine',o:['kein','keinen','nichts'],
 ex:'The plural is always keine — ein has no plural, so kein fills the gap.',tr:'There are no parking spaces here.',say:'Hier gibt es keine Parkplätze.'},

/* ---- pronomen-akk ---- */
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Ich liebe ___.',a:'dich',o:['dir','du','dein'],
 ex:'du → accusative dich. dir would be the dative („to you“).',tr:'I love you.',say:'Ich liebe dich.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Kennst du ___?',a:'ihn',o:['ihm','er','ihr'],
 ex:'er → accusative ihn. Remember: masculine accusative always ends in -n.',tr:'Do you know him?',say:'Kennst du ihn?'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Er besucht ___ am Wochenende.',a:'uns',o:['wir','unser','euer'],
 ex:'wir → uns. uns works for both accusative and dative.',tr:'He is visiting us at the weekend.',say:'Er besucht uns am Wochenende.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Der Film ist gut. Ich sehe ___ heute.',a:'ihn',o:['es','sie','ihm'],
 ex:'der Film is masculine, so „it“ becomes ihn — not es.',tr:'The film is good. I’m seeing it today.',say:'Der Film ist gut. Ich sehe ihn heute.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Die Zeitung? Ich lese ___ jeden Tag.',a:'sie',o:['es','ihn','ihr'],
 ex:'die Zeitung is feminine → sie. ihr would be the dative.',tr:'The newspaper? I read it every day.',say:'Die Zeitung? Ich lese sie jeden Tag.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Das Buch ist neu. Ich lese ___ gerade.',a:'es',o:['ihn','sie','ihm'],
 ex:'das Buch is neuter → es. Here „it“ really is es, because the German noun is a das-word.',tr:'The book is new. I’m reading it right now.',say:'Das Buch ist neu. Ich lese es gerade.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Ich verstehe ___ nicht, Herr Meier.',a:'Sie',o:['sie','dich','Ihnen'],
 ex:'Formal „you“ as an object is Sie with a capital S. Ihnen is its dative form.',tr:'I don’t understand you, Mr Meier.',say:'Ich verstehe Sie nicht, Herr Meier.'},
{gid:'pronomen-akk',lv:2,sk:'Cases',s:'Wo seid ihr? Ich suche ___ seit zehn Minuten.',a:'euch',o:['ihr','uns','euer'],
 ex:'ihr → euch. euer is the possessive („your“), not an object pronoun.',tr:'Where are you? I’ve been looking for you for ten minutes.',say:'Wo seid ihr? Ich suche euch seit zehn Minuten.'},

/* ---- pronomen-dat ---- */
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Kannst du ___ helfen?',a:'mir',o:['mich','ich','mein'],
 ex:'helfen always takes the dative → mir, never mich.',tr:'Can you help me?',say:'Kannst du mir helfen?'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Ich danke ___.',a:'dir',o:['dich','du','deiner'],
 ex:'danken is another dative verb → „Ich danke dir.“',tr:'Thank you.',say:'Ich danke dir.'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Wie geht es ___, Frau Keller?',a:'Ihnen',o:['Sie','ihnen','dir'],
 ex:'The fixed phrase takes the dative, and formal „you“ in the dative is Ihnen with a capital I.',tr:'How are you, Mrs Keller?',say:'Wie geht es Ihnen, Frau Keller?'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Das Auto gehört ___.',a:'ihm',o:['ihn','er','sein'],
 ex:'gehören takes the dative → ihm. ihn would be accusative.',tr:'The car belongs to him.',say:'Das Auto gehört ihm.'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Das Buch gefällt ___ sehr.',a:'ihr',o:['sie','ihm','ihnen'],
 ex:'gefallen takes the dative, and „to her“ is ihr. Note the thing liked is the subject.',tr:'She likes the book a lot.',say:'Das Buch gefällt ihr sehr.'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Ich schreibe ___ eine E-Mail.',a:'ihnen',o:['sie','ihm','ihr'],
 ex:'„to them“ = dative plural ihnen. The e-mail itself is the accusative object.',tr:'I’m writing them an e-mail.',say:'Ich schreibe ihnen eine E-Mail.'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Den Ball? Ich gebe ___ dem Kind.',a:'ihn',o:['ihm','er','ihnen'],
 ex:'der Ball → accusative pronoun ihn, and a pronoun always comes before a noun object.',tr:'The ball? I’m giving it to the child.',say:'Den Ball? Ich gebe ihn dem Kind.'},
{gid:'pronomen-dat',lv:2,sk:'Cases',s:'Hast du das Geld? — Ja, ich gebe es ___ morgen.',a:'dir',o:['dich','du','deine'],
 ex:'With two pronouns the accusative comes first and the dative second: „ich gebe es dir“.',tr:'Do you have the money? — Yes, I’ll give it to you tomorrow.',say:'Hast du das Geld? Ja, ich gebe es dir morgen.'},

/* ---- verben-stamm ---- */
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Du ___ sehr gut Deutsch.',a:'sprichst',o:['sprechst','spricht','sprecht'],
 ex:'sprechen changes e→i in the du-form: du sprichst.',tr:'You speak German very well.',say:'Du sprichst sehr gut Deutsch.'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Er ___ jeden Abend die Zeitung.',a:'liest',o:['lest','lesst','lese'],
 ex:'lesen changes e→ie: du liest, er liest. („lest“ is the ihr-form.)',tr:'He reads the newspaper every evening.',say:'Er liest jeden Abend die Zeitung.'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Sie ___ mit dem Bus zur Arbeit.',a:'fährt',o:['fahrt','fahrst','fahre'],
 ex:'fahren takes an Umlaut a→ä in the er/sie/es-form: sie fährt.',tr:'She goes to work by bus.',say:'Sie fährt mit dem Bus zur Arbeit.'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'___ du mir bitte das Salz?',a:'Gibst',o:['Gebst','Gibt','Gebt'],
 ex:'geben changes e→i: du gibst. („Gibt“ would need er/sie/es.)',tr:'Will you pass me the salt, please?',say:'Gibst du mir bitte das Salz?'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Was ___ du zum Frühstück?',a:'isst',o:['esst','essest','esse'],
 ex:'essen changes e→i and the stem already ends in -ss, so du isst = er isst.',tr:'What do you eat for breakfast?',say:'Was isst du zum Frühstück?'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Er ___ den Zug um acht Uhr.',a:'nimmt',o:['nehmt','nimmst','nehmmt'],
 ex:'nehmen is extra irregular: du nimmst, er nimmt — the h disappears and the m doubles.',tr:'He takes the eight o’clock train.',say:'Er nimmt den Zug um acht Uhr.'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Wir ___ morgen nach Berlin.',a:'fahren',o:['fähren','fahrt','fährt'],
 ex:'wir never changes the stem vowel — the Umlaut belongs to du and er/sie/es only.',tr:'We’re going to Berlin tomorrow.',say:'Wir fahren morgen nach Berlin.'},
{gid:'verben-stamm',lv:2,sk:'Verbs',s:'Ihr ___ zu schnell für mich.',a:'sprecht',o:['spricht','sprechst','sprichst'],
 ex:'ihr keeps the plain stem: ihr sprecht. Only du and er/sie/es change.',tr:'You (all) speak too fast for me.',say:'Ihr sprecht zu schnell für mich.'},

/* ---- verbposition ---- */
{gid:'verbposition',lv:2,sk:'Sentences',s:'Heute ___ Deutsch.',a:'lerne ich',o:['ich lerne','ich lernen','lerne mich'],
 ex:'„Heute“ fills position 1, so the verb must come second and the subject follows it.',tr:'Today I’m learning German.',say:'Heute lerne ich Deutsch.'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'Am Montag ___ zur Arbeit.',a:'fährt er',o:['er fährt','er fahrt','fahrt er'],
 ex:'The time phrase takes position 1 → verb, then subject: „Am Montag fährt er …“',tr:'On Monday he goes to work.',say:'Am Montag fährt er zur Arbeit.'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'In Berlin ___ viele Studenten.',a:'wohnen',o:['wohnt','wohne','wohnst'],
 ex:'The place phrase is position 1; the verb is second and agrees with „viele Studenten“ (plural).',tr:'Many students live in Berlin.',say:'In Berlin wohnen viele Studenten.'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'Nach der Arbeit ___ einkaufen.',a:'gehe ich',o:['ich gehe','geht ich','ich gehen'],
 ex:'„Nach der Arbeit“ is three words but one element, so it fills position 1 completely.',tr:'After work I go shopping.',say:'Nach der Arbeit gehe ich einkaufen.'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'Jeden Tag ___ meine Mutter Kaffee.',a:'trinkt',o:['trinken','trinke','trinkst'],
 ex:'Position 1 = „Jeden Tag“, position 2 = the verb, and the subject „meine Mutter“ comes after it.',tr:'Every day my mother drinks coffee.',say:'Jeden Tag trinkt meine Mutter Kaffee.'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'___ du heute Zeit?',a:'Hast',o:['Du hast','Haben','Habst'],
 ex:'A yes/no question is the exception: the verb takes position 1.',tr:'Do you have time today?',say:'Hast du heute Zeit?'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'Warum ___ du so früh auf?',a:'stehst',o:['du stehst','steht','stehen'],
 ex:'The W-word occupies position 1, so the verb is still second: „Warum stehst du …“',tr:'Why do you get up so early?',say:'Warum stehst du so früh auf?'},
{gid:'verbposition',lv:2,sk:'Sentences',s:'Weil es regnet, ___ zu Hause.',a:'bleibe ich',o:['ich bleibe','ich bleiben','bleibe mich'],
 ex:'The whole clause „Weil es regnet“ counts as position 1, so the main verb comes right after the comma.',tr:'Because it’s raining, I’m staying at home.',say:'Weil es regnet, bleibe ich zu Hause.'},

/* ---- esgibt ---- */
{gid:'esgibt',lv:2,sk:'Sentences',s:'Hier ___ es einen Supermarkt.',a:'gibt',o:['ist','sind','geben'],
 ex:'The fixed phrase is es gibt — „hier gibt es …“ after inversion.',tr:'There is a supermarket here.',say:'Hier gibt es einen Supermarkt.'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Es gibt ___ Bahnhof in der Stadt.',a:'einen',o:['ein','eine','einem'],
 ex:'es gibt takes the accusative, and der Bahnhof becomes einen Bahnhof.',tr:'There is a station in town.',say:'Es gibt einen Bahnhof in der Stadt.'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'In meiner Straße gibt es ___ Apotheke.',a:'eine',o:['ein','einen','einem'],
 ex:'die Apotheke is feminine, and feminine does not change in the accusative.',tr:'There is a pharmacy in my street.',say:'In meiner Straße gibt es eine Apotheke.'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Gibt es hier ___ Kino?',a:'ein',o:['einen','eine','einem'],
 ex:'das Kino is neuter → ein Kino, unchanged in the accusative.',tr:'Is there a cinema here?',say:'Gibt es hier ein Kino?'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Es ___ zwei Kinos in der Stadt.',a:'gibt',o:['geben','sind','ist'],
 ex:'es gibt stays singular even with a plural noun — German never says „es sind zwei Kinos“ here.',tr:'There are two cinemas in town.',say:'Es gibt zwei Kinos in der Stadt.'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Es gibt ___ Milch mehr.',a:'keine',o:['kein','keinen','nicht'],
 ex:'die Milch → keine Milch. „kein … mehr“ = none left.',tr:'There is no milk left.',say:'Es gibt keine Milch mehr.'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Was ___ es heute zum Mittagessen?',a:'gibt',o:['ist','sind','gebt'],
 ex:'„Was gibt es …?“ is the standard way to ask what is on offer.',tr:'What is there for lunch today?',say:'Was gibt es heute zum Mittagessen?'},
{gid:'esgibt',lv:2,sk:'Sentences',s:'Das ___ meine Schwester.',a:'ist',o:['gibt','gibt es','sind'],
 ex:'To identify a person use sein. es gibt is only for saying that something exists.',tr:'That is my sister.',say:'Das ist meine Schwester.'},

/* ---- moechten ---- */
{gid:'moechten',lv:2,sk:'Verbs',s:'Ich ___ einen Kaffee, bitte.',a:'möchte',o:['möchtet','möchten','möchtest'],
 ex:'ich möchte — no -t ending, exactly like the er/sie/es-form.',tr:'I’d like a coffee, please.',say:'Ich möchte einen Kaffee, bitte.'},
{gid:'moechten',lv:2,sk:'Verbs',s:'___ du mitkommen?',a:'Möchtest',o:['Möchte','Möchtet','Möchten'],
 ex:'du möchtest, and the main verb mitkommen stays an infinitive at the end.',tr:'Would you like to come along?',say:'Möchtest du mitkommen?'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Was ___ Sie trinken?',a:'möchten',o:['möchte','möchtest','möchtet'],
 ex:'The Sie-form is möchten — identical to the infinitive-style plural form.',tr:'What would you like to drink?',say:'Was möchten Sie trinken?'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Wir ___ die Rechnung, bitte.',a:'möchten',o:['möchte','möchtet','möchtest'],
 ex:'wir möchten. With a simple noun object möchten needs no second verb.',tr:'We’d like the bill, please.',say:'Wir möchten die Rechnung, bitte.'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Er ___ heute nicht arbeiten.',a:'will',o:['willt','wollt','möchtet'],
 ex:'wollen: ich will, du willst, er will — no -t on er.',tr:'He doesn’t want to work today.',say:'Er will heute nicht arbeiten.'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Ich möchte ein Zimmer ___.',a:'reservieren',o:['zu reservieren','reserviert','reserviere'],
 ex:'After möchten the main verb is a bare infinitive at the end — never with zu.',tr:'I’d like to book a room.',say:'Ich möchte ein Zimmer reservieren.'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Ihr ___ also ins Kino gehen?',a:'möchtet',o:['möchten','möchte','möchtest'],
 ex:'ihr möchtet — the only form with -t.',tr:'So you’d like to go to the cinema?',say:'Ihr möchtet also ins Kino gehen?'},
{gid:'moechten',lv:2,sk:'Verbs',s:'Im Café sagt man höflich: „Ich ___ ein Stück Kuchen.“',a:'möchte',o:['will','möchtest','wollen'],
 ex:'möchte is the polite choice; „Ich will“ is grammatical but sounds demanding to a waiter.',tr:'In a café you politely say: „I’d like a piece of cake.“',say:'Ich möchte ein Stück Kuchen.'},

/* ---- modal-basis ---- */
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Ich ___ gut schwimmen.',a:'kann',o:['kannst','können','könnt'],
 ex:'ich kann — modals drop the -e in the ich-form and change their vowel.',tr:'I can swim well.',say:'Ich kann gut schwimmen.'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Du ___ jetzt nach Hause gehen.',a:'musst',o:['muss','müsst','müssen'],
 ex:'du musst (one s in the stem, then -st). müsst is the ihr-form.',tr:'You have to go home now.',say:'Du musst jetzt nach Hause gehen.'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'___ ich bitte das Fenster öffnen?',a:'Darf',o:['Darfst','Dürfen','Darft'],
 ex:'ich darf — the same form as er/sie/es. The question puts the modal in position 1.',tr:'May I open the window, please?',say:'Darf ich bitte das Fenster öffnen?'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Wir müssen um sieben Uhr ___.',a:'aufstehen',o:['stehen auf','aufzustehen','aufgestanden'],
 ex:'The infinitive closes the bracket at the end, in one piece and with no zu.',tr:'We have to get up at seven.',say:'Wir müssen um sieben Uhr aufstehen.'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Hier ___ man nicht parken.',a:'darf',o:['darfst','dürfen','darft'],
 ex:'man always takes the er/sie/es-form → darf. nicht dürfen expresses a ban.',tr:'You’re not allowed to park here.',say:'Hier darf man nicht parken.'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Können Sie mir bitte ___?',a:'helfen',o:['hilfen','helfe','zu helfen'],
 ex:'The infinitive never changes its vowel — helfen, not „hilfen“ — and takes no zu.',tr:'Could you help me, please?',say:'Können Sie mir bitte helfen?'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Du ___ nicht mitkommen, wenn du keine Zeit hast.',a:'musst',o:['darfst','müsst','kannst'],
 ex:'nicht müssen = you don’t have to. „darfst nicht“ would forbid it.',tr:'You don’t have to come along if you have no time.',say:'Du musst nicht mitkommen, wenn du keine Zeit hast.'},
{gid:'modal-basis',lv:2,sk:'Verbs',s:'Kinder ___ hier nicht allein schwimmen — es ist verboten.',a:'dürfen',o:['müssen','können','darf'],
 ex:'A prohibition is nicht dürfen. „können nicht“ would mean they are unable to.',tr:'Children are not allowed to swim here alone — it’s forbidden.',say:'Kinder dürfen hier nicht allein schwimmen.'},

/* ---- trennbar-basis ---- */
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Ich stehe um sieben Uhr ___.',a:'auf',o:['an','ein','mit'],
 ex:'aufstehen → the prefix auf lands at the very end.',tr:'I get up at seven o’clock.',say:'Ich stehe um sieben Uhr auf.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Wir kaufen im Supermarkt ___.',a:'ein',o:['auf','an','aus'],
 ex:'einkaufen = to do the shopping → „wir kaufen … ein“.',tr:'We do our shopping at the supermarket.',say:'Wir kaufen im Supermarkt ein.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Ich rufe dich heute Abend ___.',a:'an',o:['auf','ein','mit'],
 ex:'anrufen = to phone somebody. The object dich comes before the prefix.',tr:'I’ll call you this evening.',say:'Ich rufe dich heute Abend an.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'___ du heute Abend mit?',a:'Kommst',o:['Mitkommst','Kommt','Komme'],
 ex:'Only the verb part is conjugated and moved; mit stays at the end.',tr:'Are you coming along tonight?',say:'Kommst du heute Abend mit?'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Abends ___ er gern fern.',a:'sieht',o:['fernsieht','sehen','siehst'],
 ex:'fernsehen splits, and sehen changes e→ie: „er sieht … fern“.',tr:'In the evenings he likes watching TV.',say:'Abends sieht er gern fern.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Ich muss morgen früh ___.',a:'aufstehen',o:['auf stehen','stehe auf','aufgestehen'],
 ex:'After a modal the verb is an infinitive, so it stays in one piece: aufstehen.',tr:'I have to get up early tomorrow.',say:'Ich muss morgen früh aufstehen.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Ich ___ dich nicht — sprich bitte langsamer.',a:'verstehe',o:['stehe ver','verstehst','verstehen'],
 ex:'ver- is an inseparable prefix: it never leaves the verb.',tr:'I don’t understand you — please speak more slowly.',say:'Ich verstehe dich nicht.'},
{gid:'trennbar-basis',lv:2,sk:'Verbs',s:'Wann ___ der Film an?',a:'fängt',o:['anfängt','fangt','fängst'],
 ex:'anfangen separates and changes a→ä in the er-form: „Wann fängt der Film an?“',tr:'When does the film start?',say:'Wann fängt der Film an?'},

/* ---- ortsprep ---- */
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Das Buch liegt auf ___ Tisch.',a:'dem',o:['den','der','das'],
 ex:'Location → Dativ. der Tisch becomes dem Tisch.',tr:'The book is on the table.',say:'Das Buch liegt auf dem Tisch.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Ich bin in ___ Küche.',a:'der',o:['die','dem','den'],
 ex:'die Küche in the Dativ is der Küche — feminine der, not masculine.',tr:'I’m in the kitchen.',say:'Ich bin in der Küche.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Die Katze sitzt unter ___ Stuhl.',a:'dem',o:['den','der','das'],
 ex:'sitzen describes a position, so unter takes the Dativ: unter dem Stuhl.',tr:'The cat is sitting under the chair.',say:'Die Katze sitzt unter dem Stuhl.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Das Bild hängt an ___ Wand.',a:'der',o:['die','dem','den'],
 ex:'die Wand → an der Wand. an is used for vertical surfaces.',tr:'The picture is hanging on the wall.',say:'Das Bild hängt an der Wand.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Das Auto steht vor ___ Haus.',a:'dem',o:['das','der','den'],
 ex:'das Haus in the Dativ is dem Haus — neuter and masculine share dem.',tr:'The car is parked in front of the house.',say:'Das Auto steht vor dem Haus.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Die Kinder spielen ___ Garten.',a:'im',o:['in','in den','ins'],
 ex:'Nothing is moving → Dativ → in dem, which always shortens to im.',tr:'The children are playing in the garden.',say:'Die Kinder spielen im Garten.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Wir warten ___ Bahnhof.',a:'am',o:['an der','an die','ans'],
 ex:'der Bahnhof → an dem → am Bahnhof. „an der“ would need a feminine noun.',tr:'We’re waiting at the station.',say:'Wir warten am Bahnhof.'},
{gid:'ortsprep',lv:2,sk:'Prepositions',s:'Die Apotheke ist zwischen ___ Bäckerei und dem Kino.',a:'der',o:['die','dem','den'],
 ex:'zwischen takes the Dativ for a location, and die Bäckerei becomes der Bäckerei.',tr:'The pharmacy is between the bakery and the cinema.',say:'Die Apotheke ist zwischen der Bäckerei und dem Kino.'},

/* ---- und-aber ---- */
{gid:'und-aber',lv:2,sk:'Sentences',s:'Ich bin müde, ___ ich arbeite weiter.',a:'aber',o:['denn','sondern','weil'],
 ex:'A contrast with no negative in front → aber. The second clause keeps its normal order.',tr:'I’m tired, but I keep working.',say:'Ich bin müde, aber ich arbeite weiter.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Wir bleiben zu Hause, ___ es regnet.',a:'denn',o:['aber','sondern','dass'],
 ex:'denn gives the reason and changes nothing: „…, denn es regnet.“',tr:'We’re staying at home, because it’s raining.',say:'Wir bleiben zu Hause, denn es regnet.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Das ist kein Tee, ___ Kaffee.',a:'sondern',o:['aber','denn','oder'],
 ex:'After a negative, a correction uses sondern („not X but Y“).',tr:'That isn’t tea, it’s coffee.',say:'Das ist kein Tee, sondern Kaffee.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Möchtest du Tee ___ Kaffee?',a:'oder',o:['und','aber','denn'],
 ex:'oder offers an alternative and never affects the word order.',tr:'Would you like tea or coffee?',say:'Möchtest du Tee oder Kaffee?'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Ich wohne in Wien ___ ich arbeite in Graz.',a:'und',o:['sondern','dass','weil'],
 ex:'und simply adds a second main clause; both halves keep the verb in position 2.',tr:'I live in Vienna and I work in Graz.',say:'Ich wohne in Wien und ich arbeite in Graz.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Ich komme nicht mit, denn ___ keine Zeit.',a:'ich habe',o:['habe ich','ich hab','habe'],
 ex:'denn sits in position 0, so the clause starts again from scratch: subject, then verb.',tr:'I’m not coming along, because I have no time.',say:'Ich komme nicht mit, denn ich habe keine Zeit.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Es regnet, aber ___ trotzdem spazieren.',a:'ich gehe',o:['gehe ich','ich gehen','geht ich'],
 ex:'aber changes nothing either — no inversion after it.',tr:'It’s raining, but I’m going for a walk anyway.',say:'Es regnet, aber ich gehe trotzdem spazieren.'},
{gid:'und-aber',lv:2,sk:'Sentences',s:'Ich bleibe zu Hause, weil es ___.',a:'regnet',o:['regnet es','es regnet','regne'],
 ex:'weil is not one of the five: it is subordinating and pushes the verb to the very end.',tr:'I’m staying at home because it’s raining.',say:'Ich bleibe zu Hause, weil es regnet.'},

/* ---- laender ---- */
{gid:'laender',lv:2,sk:'Vocabulary',s:'Ich komme ___ Deutschland.',a:'aus',o:['von','nach','in'],
 ex:'Origin (Woher?) → aus. „von“ is for people and places you leave, not countries.',tr:'I come from Germany.',say:'Ich komme aus Deutschland.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Wir fahren im Sommer ___ Italien.',a:'nach',o:['in','zu','aus'],
 ex:'Destination (Wohin?) with an article-less country → nach Italien.',tr:'In summer we’re going to Italy.',say:'Wir fahren im Sommer nach Italien.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Sie wohnt ___ Berlin.',a:'in',o:['nach','aus','an'],
 ex:'Location (Wo?) with a city → in Berlin.',tr:'She lives in Berlin.',say:'Sie wohnt in Berlin.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Mein Freund fliegt ___ die Türkei.',a:'in',o:['nach','aus','zu'],
 ex:'die Türkei has an article, so the destination is in + Akkusativ — never „nach die Türkei“.',tr:'My friend is flying to Turkey.',say:'Mein Freund fliegt in die Türkei.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Sie kommt ___ der Schweiz.',a:'aus',o:['von','nach','in'],
 ex:'Origin from an article-country → aus + Dativ: aus der Schweiz.',tr:'She comes from Switzerland.',say:'Sie kommt aus der Schweiz.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Ich lebe seit zehn Jahren ___ Iran.',a:'im',o:['in','nach','in die'],
 ex:'der Iran, location → in dem Iran → im Iran.',tr:'I’ve been living in Iran for ten years.',say:'Ich lebe seit zehn Jahren im Iran.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Er spricht sehr gut ___.',a:'Französisch',o:['französisch','Frankreich','Franzose'],
 ex:'A language is a noun, so it is capitalised: Französisch. Lowercase französisch is the adjective.',tr:'He speaks French very well.',say:'Er spricht sehr gut Französisch.'},
{gid:'laender',lv:2,sk:'Vocabulary',s:'Anna ist ___ — sie kommt aus Wien.',a:'Österreicherin',o:['Österreich','österreicherin','Österreicherinnen'],
 ex:'Feminine nationalities add -in, are capitalised, and take no article after sein.',tr:'Anna is Austrian — she comes from Vienna.',say:'Anna ist Österreicherin.'},

/* ---- plural-basis ---- */
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Ich habe zwei ___.',a:'Brüder',o:['Bruders','Brudern','Brudere'],
 ex:'der Bruder → die Brüder: only the vowel changes, no ending.',tr:'I have two brothers.',say:'Ich habe zwei Brüder.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Im Zimmer stehen drei ___.',a:'Stühle',o:['Stuhle','Stuhls','Stühlen'],
 ex:'der Stuhl → die Stühle: -e plus Umlaut. „Stühlen“ is the Dativ plural.',tr:'There are three chairs in the room.',say:'Im Zimmer stehen drei Stühle.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Wir haben vier ___.',a:'Kinder',o:['Kinds','Kindern','Kinde'],
 ex:'das Kind → die Kinder: the -er plural, with no Umlaut here.',tr:'We have four children.',say:'Wir haben vier Kinder.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Auf dem Tisch liegen zwei ___.',a:'Bücher',o:['Buchs','Buche','Büchern'],
 ex:'das Buch → die Bücher: -er plus Umlaut.',tr:'There are two books on the table.',say:'Auf dem Tisch liegen zwei Bücher.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'In der Straße stehen viele ___.',a:'Autos',o:['Aute','Auten','Autoen'],
 ex:'das Auto → die Autos: loanwords take -s.',tr:'There are lots of cars in the street.',say:'In der Straße stehen viele Autos.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'An der Schule arbeiten drei ___.',a:'Lehrerinnen',o:['Lehrerins','Lehrerine','Lehrerinen'],
 ex:'die Lehrerin → die Lehrerinnen: -in doubles the n and adds -en.',tr:'Three female teachers work at the school.',say:'An der Schule arbeiten drei Lehrerinnen.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Ich spiele mit meinen ___.',a:'Kindern',o:['Kinder','Kinds','Kindes'],
 ex:'In the Dativ plural the noun adds -n: mit den Kindern, mit zwei Freunden.',tr:'I play with my children.',say:'Ich spiele mit meinen Kindern.'},
{gid:'plural-basis',lv:2,sk:'Vocabulary',s:'Zwei ___ warten draußen.',a:'Lehrer',o:['Lehrers','Lehrere','Lehreren'],
 ex:'Nouns ending in -er, -el, -en or -chen add nothing: der Lehrer → die Lehrer.',tr:'Two teachers are waiting outside.',say:'Zwei Lehrer warten draußen.'},

/* ---- datum-wochentag ---- */
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'___ Montag gehe ich zum Arzt.',a:'Am',o:['Im','An','In'],
 ex:'Days take am (= an dem), because every day is a der-word.',tr:'On Monday I’m going to the doctor.',say:'Am Montag gehe ich zum Arzt.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'___ Januar ist es sehr kalt.',a:'Im',o:['Am','In','An'],
 ex:'Months take im (= in dem): im Januar, im Mai, im Dezember.',tr:'In January it’s very cold.',say:'Im Januar ist es sehr kalt.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'Wir fahren ___ Sommer nach Spanien.',a:'im',o:['am','in','an'],
 ex:'Seasons behave like months: im Sommer, im Winter.',tr:'In summer we go to Spain.',say:'Wir fahren im Sommer nach Spanien.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'Mein Kurs beginnt ___ Dienstag.',a:'am',o:['im','an','um'],
 ex:'am for days; um is only for clock times („um acht Uhr“).',tr:'My course starts on Tuesday.',say:'Mein Kurs beginnt am Dienstag.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'Heute ist ___.',a:'Freitag',o:['am Freitag','im Freitag','an Freitag'],
 ex:'When you just name the day, use no preposition at all: „Heute ist Freitag.“',tr:'Today is Friday.',say:'Heute ist Freitag.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'___ Wochenende bleibe ich zu Hause.',a:'Am',o:['Im','In','An'],
 ex:'das Wochenende also takes am: am Wochenende.',tr:'At the weekend I stay at home.',say:'Am Wochenende bleibe ich zu Hause.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'___ Nacht kann ich nicht schlafen.',a:'In der',o:['Am','Im','An der'],
 ex:'die Nacht is the exception: in der Nacht — but am Morgen, am Abend.',tr:'At night I can’t sleep.',say:'In der Nacht kann ich nicht schlafen.'},
{gid:'datum-wochentag',lv:2,sk:'Numbers',s:'Mein Geburtstag ist ___ dritten Mai.',a:'am',o:['im','an','um'],
 ex:'Dates use am + the ordinal: am dritten Mai, am ersten Januar.',tr:'My birthday is on the third of May.',say:'Mein Geburtstag ist am dritten Mai.'},

/* ---- adjektiv-praedikativ ---- */
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Der Kaffee ist ___.',a:'heiß',o:['heiße','heißer','heißen'],
 ex:'After ist the adjective takes no ending. („heißer“ would mean „hotter“.)',tr:'The coffee is hot.',say:'Der Kaffee ist heiß.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Die Suppe ist ___.',a:'kalt',o:['kalte','kalten','kaltes'],
 ex:'Feminine makes no difference here — after sein the adjective is bare.',tr:'The soup is cold.',say:'Die Suppe ist kalt.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Das Buch ist ___.',a:'interessant',o:['interessante','interessantes','interessanten'],
 ex:'„das interessante Buch“ needs an ending; „das Buch ist interessant“ does not.',tr:'The book is interesting.',say:'Das Buch ist interessant.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Die Kinder sind ___.',a:'müde',o:['müden','müder','müdes'],
 ex:'Plural changes nothing: the predicative adjective never takes an ending.',tr:'The children are tired.',say:'Die Kinder sind müde.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Im Winter wird es früh ___.',a:'dunkel',o:['dunkle','dunkles','dunklen'],
 ex:'werden counts too: the adjective after it stays in its dictionary form.',tr:'In winter it gets dark early.',say:'Im Winter wird es früh dunkel.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Bitte bleib ___!',a:'ruhig',o:['ruhige','ruhiger','ruhigen'],
 ex:'bleiben is the third verb in the family: sein, werden, bleiben → no ending.',tr:'Please stay calm!',say:'Bitte bleib ruhig!'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Die Wohnung ist ___ und hell.',a:'groß',o:['große','großes','großen'],
 ex:'Both adjectives stand after ist, so both stay bare: „groß und hell“.',tr:'The flat is big and bright.',say:'Die Wohnung ist groß und hell.'},
{gid:'adjektiv-praedikativ',lv:2,sk:'Adjectives',s:'Das Haus ist ___, aber schön.',a:'alt',o:['altes','alte','alten'],
 ex:'After ist: no ending. Compare „ein altes Haus“, where the adjective stands in front of the noun.',tr:'The house is old but lovely.',say:'Das Haus ist alt, aber schön.'},

/* ---- du-sie ---- */
{gid:'du-sie',lv:2,sk:'Beginner',s:'Wie ___ Sie?',a:'heißen',o:['heißt','heiße','heißst'],
 ex:'The Sie-form equals the infinitive: Sie heißen, Sie kommen, Sie wohnen.',tr:'What is your name? (formal)',say:'Wie heißen Sie?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Woher ___ du?',a:'kommst',o:['kommt','kommen','komme'],
 ex:'du always ends in -st.',tr:'Where are you from? (informal)',say:'Woher kommst du?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Guten Tag, Herr Müller, ___ Sie Zeit?',a:'haben',o:['hast','habt','habe'],
 ex:'„Herr Müller“ means Sie, and the Sie-form of haben is haben.',tr:'Hello, Mr Müller, do you have time?',say:'Guten Tag, Herr Müller, haben Sie Zeit?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Kinder, ___ ihr Hunger?',a:'habt',o:['hast','haben','habe'],
 ex:'Several people you know → ihr habt.',tr:'Kids, are you hungry?',say:'Kinder, habt ihr Hunger?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Ist das ___ Auto, Frau Klein?',a:'Ihr',o:['dein','euer','ihre'],
 ex:'The formal possessive is Ihr with a capital I; das Auto is neuter, so it takes no ending.',tr:'Is that your car, Mrs Klein?',say:'Ist das Ihr Auto, Frau Klein?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Anna, ist das ___ Fahrrad?',a:'dein',o:['Ihr','euer','deine'],
 ex:'First name → du, so the possessive is dein; das Fahrrad is neuter → no ending.',tr:'Anna, is that your bike?',say:'Anna, ist das dein Fahrrad?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Herr Weber, ___ Sie mir bitte helfen?',a:'können',o:['kannst','könnt','kann'],
 ex:'Sie + können = können. „kann Sie“ mixes the er-form with the formal pronoun.',tr:'Mr Weber, could you help me please?',say:'Herr Weber, können Sie mir bitte helfen?'},
{gid:'du-sie',lv:2,sk:'Beginner',s:'Lisa und Tom, woher ___ ihr?',a:'kommt',o:['kommen','kommst','komme'],
 ex:'Two friends → ihr, and the ihr-form ends in -t: ihr kommt.',tr:'Lisa and Tom, where are you from?',say:'Lisa und Tom, woher kommt ihr?'}

];
